3‬يف ‪1433/01/03‬هــ‪ ،‬و املصـ َّـدق مــن فــرع وزارة‬\n‫املكرمــة بتاريــخ ‪1433/12/26‬هــ‪ ،‬و مــن‬             ‫َّ‬       ‫مكــة‬\n                                                                  ‫اخلارجيــة مبنطقــة َّ‬\n‫املتضمــن‪:‬‬\n     ‫ِّ‬            ‫فــرع وزارة العــدل باملدينــة املنـ َّـورة بتاريــخ ‪1434/02/13‬هــ‪ .‬و‬\n‫«وفــاة‪ ......... /‬بتاريــخ ‪1433/01/01‬هــ‪ ،‬و انحصــار إرثــه يف‪ :‬زوجتــه‪/‬‬\n‫‪ ، .........‬و أوالدهــا منــه كلّ مــن‪... ......... /‬و زوجتــه‪ ،........./‬و بناتهــا‬\n‫ثانيــا‪:‬‬\n    ‫القاصــرات منــه كلّ مــن‪ ......... /‬ال وارث لــه ســواهما» ا‪.‬هــ‪ً .‬‬\n‫اجلزئيــة يف‬\n          ‫َّ‬        ‫الصــادر مــن احملكمــة‬  ‫ـرعي القطعـ ُّـي بالقناعــة َّ‬  ‫الشـ ُّ‬\n                                                                                  ‫القــرار َّ‬\n\n\n                                                                                                 ‫‪266‬‬\n\f      ‫املتضمــن‪:‬‬‫ِّ‬        ‫املدينــة املنـ َّـورة برقــم (‪ )3353489‬يف ‪1433/10/30‬هــ‪ ،‬و‬\n      ‫ـئولية احلــادث‪ ،‬و قناعتــه‬        ‫املدعــى عليــه ـ ـ ـ ـ بنســبة (‪ )%50‬مــن مسـ َّ‬                 ‫«إدانــة َّ‬\n      ‫ـاء علــى مــا تقـ َّـدم‪ ،‬و مبــا‬      ‫أن عليــه ك َّفــارة قتــل اخلطأ»ا‪.‬هــ‪ .‬فبنـ ً‬             ‫بذلــك‪ ،‬و َّ‬\n      ‫املدعــى‬     ‫أن َّ‬\n                       ‫املدعيــان أصال ـ ًة و وكال ـ ًة ا َّدعيــا مبــا ا َّدعيــا بــه‪ ،‬و مبــا َّ‬                ‫أن َّ‬   ‫َّ‬\n      ‫املدعــي أصال ـ ًة و وكال ـ ًة جمل ـ ًة و‬             ‫عليــه صــادق علــى مــا جــاء يف دعــوى َّ‬\n      ‫ن؛ و ل ــما هــو مقـ َّـر ٌر‬ ‫املدعيـ ِ‬  ‫ـورث َّ‬  ‫ـتعد بتســليم نصــف ديــة مـ ِّ‬      ‫تفصيـ ًـا؛ و اسـ َّ‬\n      ‫ـبب لزمتــه‬     ‫معصومــا مباشــر ًة أو بسـ ٍ‬ ‫ً‬             ‫أن كلَّ مــن أتلــف إنســانًا‬        ‫فق ًهــا مــن َّ‬\n      ‫(ينظــر‪ :‬الفــروع ‪ ،3/6‬اإلقنــاع ‪ ،139/4‬الـ َّـروض املُر ِبــع ‪)963/2‬؛ و‬                                 ‫ديتــه َّ‬\n      ‫املدعــى عليــه بــأن يدفــع نصــف‬             ‫جلميــع مــا ســلف‪ ،‬فقــد حكمـ ُـت بإلــزام َّ‬\n         ‫ن‪ ،‬و قدرهــا مائــة و خمســن ألــف (‪ )150,000‬ريــالٍ‬                           ‫املدعيـ ِ‬  ‫ـورث َّ‬       ‫ديــة مـ ِّ‬\n                                                                              ‫ن أصال ـ ًة‪،‬‬       ‫للمدعي ـ ِ‬  ‫ـال َّ‬      ‫حـ ً‬\n      ‫الزوجتــن ـ ـ ــ‪ ،‬و ـ ـ و‬       ‫أن نصيــب َّ‬        ‫ن مبــا يلــي‪َّ /‬أو ًل‪َّ :‬‬  ‫وأفهمـ ُـت املتداعي ـ ِ‬\n      ‫ـكل واحــد ٍة منهمــا مبل ـ ٌغ قــدره تســع ُة آالف و ثالثمائ ـ ٍة و‬                     ‫ـ ـ ال ُّثمــن‪ ،‬لـ ٍّ‬\n      ‫ـظ‬   ‫للذكــر مثــل حـ ِّ‬   ‫خمس ـ ٌة و ســبعون (‪ )9,375‬ريــالٍ ‪ ،‬و الباقــي لــأوال ِد َّ‬\n      ‫ا ُألنثيــن؛ فلــكلِّ ابـ ٍـن مبلـ ٌغ قــدره خمســة عشــر ألــف و أربعمائــة و واحـ ٌـد‬\n      ‫ـال و ثمانيــة عشــر (‪ )15,441/18‬هلل ـ ًة‪ ،‬و لــكلِّ بنـ ٍـت‬                                ‫و أربعــون ريـ ً‬\n      ‫ـال و تســع ٌة و خمســون‬             ‫آالف و ســبعمائ ٍة و عشــرون ريـ ً‬        ‫مبلـ ٌغ قــدره ســبع ُة ٍ‬\n      ‫ثانيــا‪ :‬يكــون نصيــب القاصــرات مبل ًغــا قدره ســبع ُة‬                     ‫(‪ )7,720/59‬هللـ ًة‪ً .‬‬\n      ‫ريال و تســع ٌة و خمســون (‪ )7,720/59‬هلل ًٍة‬                     ‫آالف و ســبعمائ ٍة و عشــرون ً‬                  ‫ٍ‬\n      ‫الرجــوع علــى عاقل ِتـ ِه‬    ‫للمدعــى عليــه حـ َّـق ُّ‬    ‫أن َّ‬  ‫لــكل واحــدة منهــن‪ .‬ثال ًثــا‪َّ :‬‬\n      ‫ن‪ ،‬قنعــا بــه‪ ،‬و‬       ‫صدق ْتـ ُه‪ .‬و بإعــان ا ُحلكــم علــى املتداعيـ ِ‬           ‫متــى ُو ِجـ َـدت و َّ‬\n      ‫ـفوعا بصورة ضبطه مع كامــل أوراق املعاملة‬        ‫أمــرت برفــع ا ُحلكــم ـ ـ مشـ ً‬\n      ‫ـ ـ إلــى محكمــة االســتئناف؛ لتدقيقــه عمـ ًـا باملــا َّدة (‪ )179‬مــن نظــام‬\n\n\n‫‪267‬‬\n\f‫نفيذيــة‪ ،‬و ُحـ ِّـر َر يف ‪1434/02/13‬هــ‪،‬‬    ‫َّ‬           ‫ـرعية و لوائحــه ال َّت‬\n                                                                               ‫الشـ َّ‬\n                                                                                    ‫املرافعــات َّ‬\n‫محمــدٍ ‪ ،‬و علــى آلــه‬   ‫نبينــا َّ‬\n                                  ‫و بــاهلل ال َّتوفيــق‪ ،‬و ص َّلــى اهلل و س ـلَّم علــى ِّ‬\n                                                                              ‫وصحبــه أجمعــن ‪.‬‬\n‫أمــا‬‫الســام علــى مــن ال نبـ َّـي بعــده ‪َّ ...‬‬     ‫الصــاة و َّ‬       ‫احلمــد هلل وحــده‪ ،‬و َّ‬\n‫املكرمــة‬ ‫َّ‬        ‫مبكــة‬\n                       ‫بعــد‪ :‬فقــد عــادت املعاملــة مــن محكمــة االســتئناف َّ‬\n‫باخلطــاب رقــم (‪ )34500112‬يف ‪1434/03/08‬هــ‪ ،‬و قُ ِّيــدت بأســاس‬\n‫رفقــا بهــا‬     ‫احملكمــة برقــم (‪ )34/664919‬يف ‪1434/03/13‬هــ‪ُ ،‬م ً‬\n‫الصــادر م َّنــي برقــم (‪ )3437583‬يف ‪1434/02/16‬هــ‪ُ ،‬مظ َّهـ ًـرا‬                      ‫اإلعــام َّ‬\n‫اجلزائيــة الثَّالثــة برقــم (‪ )3452449‬يف‬      ‫َّ‬              ‫الدائــرة‬\n                                                                       ‫الصــادر مــن َّ‬\n                                                                                      ‫بالقــرار َّ‬\n‫الصك‪،‬‬         ‫ـص احلاجــة منــه‪« :‬و بدراســة َّ‬    ‫املتضمــن مــا نـ ُّ‬\n                                                                    ‫ِّ‬      ‫‪1434/03/01‬هــ‪ ،‬و‬\n‫و صــورة ضبطـهِ‪ ،‬تقـ َّـررت املوافقــة علــى احلُكم»ا‪.‬هــ؛ و للبيــان ُحـ ِّـر َر يف‬\n‫نبينــا‬‫‪1434/03/18‬هــ‪ ،‬و بــاهلل ال َّتوفيــق‪ ،‬و ص َّلــى اهلل و س ـلَّم علــى ِّ‬\n                              ‫محمــدٍ ‪ ،‬و علــى آلــه و صحبــه أجمعــن‪،،،،،،،.‬‬                ‫َّ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n‫‪ :‬فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n‫إلينــا شــفع خطــاب فضيلــة رئيــس احملكمــة العامــة باملدينــة املنــورة رقــم‬\n‫‪ 34/289590‬وتاريــخ ‪1434/2/18‬ه ـ املشــتملة علــى القــرار الصــادر‬\n‫مــن فضيلــة الشــيخ‪ /‬القاضــي باحملكمــة العامــة باملدينــة املنــورة املــؤرخ‬\n‫يف ‪1434/2/16‬ه ـ واملســجل بعــدد ‪ ، 3437583‬املتضمــن دعــوى ورثــة‬\n‫‪ ........./‬ضــد‪ ........./‬يف ديــة احملكــوم فيــه مبــا ّدون بباطــن الصــك‬\n‫‪.‬وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم واهلل‬\n             ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n                                                                                                      ‫‪268‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":262,"source_page_end":268,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"163d7461dd409881558f055bbb745a34d50a065a2c7f0e64a3fa9c6b4c7a48db","normalized_text_hash":"c1adaca0196d2bf086f4a606fe1d731f4fb810239986b8c6a7d4a19fd00b9a62","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p262-3437583"},{"id":"cad3eb1d-1557-5d27-a9b1-7ee535294fad","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية متوفى -حادث مروري -ال عذر ملن أقر -كفارة قتل اخلطأ داء -احلكم بإلزام املدعى عليه بدفع ما جتب على القاتل ابت يخصه من الدية بحسب نسبته يف اخلطأ -رفع احلكم حملكمة الاستئناف لوجود قاصر .","document_number":"3441472","case_number":"33235684","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/19","year":"1434","subject":"دية متوفى -حادث مروري -ال عذر ملن أقر -كفارة قتل اخلطأ داء -احلكم بإلزام املدعى عليه بدفع ما جتب على القاتل ابت يخصه من الدية بحسب نسبته يف اخلطأ -رفع احلكم حملكمة الاستئناف لوجود قاصر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/2/19 :‬هـ َر ْق ُم‬\n                               ‫ُ‬                ‫َر ْق ُم َّ‬\n                                   ‫الص ِّك‪3441472 :‬‬\n                                    ‫الدعوى‪33235684 :‬‬\n                  ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                        ‫‪ 34168222‬تاريخه‪1434/3/22 :‬هـ‬\n\n\n         ‫ديــة متوفــى‪ -‬حــادث مــروري ‪ -‬ال عــذر ملــن أقــر ‪ -‬كفــارة قتــل اخلطــأ‬\n         ‫ـداء ‪ -‬احلكــم بإلــزام املدعــى عليــه بدفــع مــا‬\n                                                         ‫جتــب علــى القاتــل ابتـ ً‬\n         ‫يخصــه مــن الديــة بحســب نســبته يف اخلطــأ ‪ -‬رفــع احلكــم حملكمــة‬\n                                                       ‫االســتئناف لوجــود قاصــر ‪.‬‬\n\n\n\n\n                                                ‫‪ .1‬القاعدة الفقهية ( ال عذر ملن أقر ) ‪.‬‬\n         ‫‪ .2‬قــال محمــد الكلبــي ـ رحمــه اهلل ـ يف كتــاب القوانــن الفقهيــة (‪)257‬‬\n                          ‫‪ « :‬فــرع ‪ :‬جتــب علــى القاتــل اخلطــأ الكفــارة مــع الديــة » ‪.‬‬\n         ‫‪ .3‬قــال ابــن مفلــح ـ رحمــه اهلل ـ يف الفــروع ( ‪ « : ) 5/10‬فائــدة مــا حتملــه‬\n         ‫ـداء أو علــى القاتــل ثــم حتملــه عنــه فيــه‬ ‫العاقلــة هــل يجــب عليهــا ابتـ ً‬\n                                                                                 ‫قــوالن » ‪.‬‬\n                   ‫‪ .4‬قال الشيخ محمد بن إبراهيم يف فتاويه ورسائله ‪: 353/11‬‬\n         ‫ـداء ال العاقلــة وكان الواجــب يف اجلنايــة‬        ‫« القاتــل يتحملهــا ابتـ ً‬\n         ‫ممــا حتملــه العاقلــة وقــد حضــر ملجلــس احلكــم اجلانــي فهــل يحكــم‬\n         ‫بالواجــب علــى اجلانــي ثــم حتملــه العاقلــة أو يحكــم علــى العاقلــة‬\n         ‫مــع غيبتهــا ألن حضــور العاقلــة ومعرفتهــا مــن الصعــب ؟ اجلــواب‬\n         ‫‪ :‬ألوليــاء الــدم مطالبــة القاتــل ومحاكمتــه عنــد احلاكــم ليحكــم‬\n                                 ‫بثبــوت القتــل وليــس لهــم مطالبــة غيــره »‪.‬‬\n                                 ‫‪ .5‬املادة ( ‪ ) 55‬من نظام املرافعات الشرعية ‪.‬‬\n‫‪269‬‬\n\f‫ادعــى الوكيــل الشــرعي عــن ورثــة املتوفــى أن مورثهــم توفــى بحــادث‬\n‫مــروري وقــد أديــن املدعــى عليــه بنســبة ‪ % 100‬ويطلــب إلــزام املدعــى‬\n‫عليــه بدفــع كامــل الديــة‪ ،‬صــادق املدعــى عليــه علــى وقــوع احلــادث‬\n‫وذكــر أن نســبة احلــادث بحقــه ‪ % 25‬ليــس ‪ % 100‬وال مانــع لديــه مــن‬\n‫تســليم ‪ % 25‬مــن الديــة حســب تقريــر املــرور الصــادر بحقــه‪ ،‬مت االطــاع‬\n‫علــى القــرار الشــرعي الصــادر مــن احملكمــة اجلزائية املتضمن أن نســبة‬\n‫احلــادث تقــع بحــق املدعــى عليــه بنســبة ‪ ، % 25‬طلــب املدعــي وكالــة‬\n‫إعــادة املعاملــة للمــرور لدراســتها مــرة أخــرى لعــدم قناعتــه بتقريــر املــرور‬\n‫املوجــود ضمــن طيــات املعاملــة املتضمــن إدانــة املدعــى عليــه بنســبة‬\n‫‪ ،%25‬مت إحالتهــا للجهــة املختصــة لتزويــد احملكمــة بقــرار آخــر‪ ،‬ثــم‬\n‫يف جلســة حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه فقــرر ناظــر‬\n‫القضيــة الســير يف الدعــوى ثــم قــام املدعــي وكالــة بإحضــار وكالــة‬\n‫جديــدة تتضمــن توكيــل الولــي علــى القاصــر املدعــي وكالــة باســتالم‬\n‫جميــع مســتحقات املتوفــى وإكمــال جميــع اإلجــراءات النظاميــة‪،‬‬\n‫أهــل العلــم يــرون أن احلكــم علــى القاتــل ابتــداء بالديــة ثــم تتحملــه‬\n‫العاقلــة‪ ،‬احلكــم علــى املدعــى عليــه الغائــب بتســليم املدعــي وكالــة‬\n‫‪ % 25‬مــن الديــة‪ ،‬مت قســمة املبلــغ علــى الورثــة حســب امليــراث الشــرعي‬\n‫ومت توضيــح نصيــب القاصــر‪ ،‬مت التوضيــح أنــه ســيدفع مبلــغ القاصــرة‬\n‫لوكيــل الولــي ألن القاصــرة ووليهــا خــارج البــاد‪ ،‬إفهــام املدعــى عليــه‬\n‫بــأن عليــه كفــارة قتــل اخلطــأ‪ ،‬قنــع املدعــي وكالــة باحلكــم واحلكــم‬\n‫قابــل لالســتئناف لوجــود القاصــرة واحلكــم حضــوري يف حــق املدعــى‬\n\n                                                                                        ‫‪270‬‬\n\f      ‫عليــه خاضــع لالســتئناف‪ ،‬حضــر املدعــى عليــه يف جلســة أخــرى وقــرر‬\n      ‫قناعتــه باحلكــم‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪ -‬مت تســليم‬\n      ‫الشــيك وقــرر املدعــي وكالــة بأنــه ليــس لديــه وهــو موكليــه أي دعــوى‬\n      ‫ضــد املدعــى عليــه واعتبــار هــذه القضيــة منتهيــة ومت التهميــش علــى‬\n                                                        ‫الضبــط والصــك بذلــك ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 33235684‬وتاريــخ ‪1433/04/04‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 33629013‬وتاريــخ ‪1433/04/04‬ه ـ واملتعلقــة‬\n      ‫بدعــوى ورثــة ‪...‬ضــد ‪...‬و‪......‬يف مطالبــة بديــة متوفــى بحــادث مــروري ويف‬\n             ‫يــوم الثالثاء‪1433/06/24‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n      ‫‪11 : 20‬صباحــا وفيهــا حضــر املدعــي بالوكالــة ‪......‬ســوداني اجلنســية‬\n      ‫يحمــل رخصــة إقامــة رقــم ‪ 2128423999‬حالــة كونــه وكيــل عــن‬\n      ‫‪ ......‬و‪...‬و‪...‬مبوجــب التوكيــل الشــرعي الصــادر مــن محكمــة االحــوال‬\n      ‫الشــخصية ‪...‬بجمهوريــة الســوادن برقــم ‪2011/124‬م واملصــدق مــن‬\n      ‫ســفارة اململكــة العربيــة الســعودية يف اخلرطــوم برقــم ‪ 29107‬يف ‪/27‬ذو‬\n      ‫القعدة‪1432/‬ه ـ واملصــادق عليــه مــن فــرع وزارة العــدل مبحافظــة جــدة‬\n      ‫برقــم ‪ 3526‬يف ‪1433/5/3‬ه ـ واملخــول لــه وكيــل يقــوم مقامنا إلســتالم‬\n      ‫جميــع االســتحقاقات والديــة وصــرف الشــيكات وكلمــا يتعلــق بحقوق‬\n      ‫املرحــوم ‪...‬وإكمــال كل االجــراءات املطلوبــة ولــه حــق التوقيــع علــى‬\n      ‫املســتندات كمــا لــه حــق املقاضــاة ورفــع الدعــاوي وحضــور اجللســات‬\n\n‫‪271‬‬\n\f‫أمــام احملاكــم كمــا لــه حــق االســتئناف أمــام احملكمــة املختصــة‬\n‫توكيــا عامــا فيمــا ورد وادعــى علــى احلاضــر معــه باملجلــس الشــرعي‬\n‫‪...‬و‪... ...‬يحمــل بطاقــة الهويــة الوطنيــة رقــم ‪...‬قائــا يف دعــواه إن مــورث‬\n‫موكلــي قــد تــويف رحمــه اهلل تعالــى يف ‪1432/7/8‬ه ـ وانحصــر إرثــه‬\n‫يف والــده ‪...‬ووالدتــه ‪...‬ويف زوجتــه الباقيــة بعصمتــه ‪...‬ويف بنتــه منهــا‬\n‫القاصــر ‪ ...‬وعمرهــا ســنة ونصــف دون وارث ســواهم كمــا ثبــت أن جــد‬\n‫القاصــرة هــو الولــي الشــرعي لهــا وذلــك مبوجــب الصــك الصــادر مــن‬\n‫جمهوريــة الســودان ‪....‬محاكــم شــرعية إعــام أولــي برقــم ‪2011/69‬م‬\n‫محكمــة األحــوال الشــخصية ‪...‬واملصــدق مــن وزارة العــدل برقــم ‪3525‬‬\n‫يف ‪1433/5/3‬ه ـ ومــن اخلارجيــة برقــم ‪ 29110‬يف ‪1432/11/27‬ه ـ‬\n‫وقــد تســبب املدعــى عليــه هــذا احلاضــر يف وفــاة مــورث موكلــي حيــث‬\n‫أنــه كان بجانــب الطريــق املســمى بطريــق الســيل مكــة الطائــف وإذا‬\n‫باملدعــى عليــه يســتقل ســيارة مــن نــوع ‪ ....‬رقــم اللوحــة ‪ ...‬فقــام بدهــس‬\n‫مــورث موكلــي ممــا أدى الــى وفاتــه وقــد أديــن املدعــى عليــه يف هــذا‬\n‫احلــادث بنســبة ‪ %100‬حيــث أن املدعــى عليــه كان يســير بســرعة (‪)140‬‬\n‫كيلــوا متــر يف الســاعة لــذا فموكلــي يطلبــون إلــزام املدعــى عليــه بــأن‬\n‫يدفــع لهــم الديــة وهــي مبلــغ ثالثمائــة ألــف ريــال ســعودي هــذه دعــواي‬\n‫وبســؤال املدعــى عليــه عــن دعــوى املدعــي بالوكالــة أجــاب قائــا كل‬\n‫مــا ذكــره املدعــي مــن قيامــي بدهــس مــورث موكليــه فهــذا صحيــح‬\n‫وهــذا قضــاء وقــدر وإذا نــزل القضــاء ضــاق الفضــاء وقــد كنــت أســتقل‬\n‫الســيارة املوصوفــة يف دعــوى املدعــي وقــد إنتقــل مــورث موكلــي املدعي‬\n‫الــى رحمــة اهلل فهــذا كلــه صحيــح أمــا مــا ذكــره مــن إدانتــي بنســبة‬\n‫‪ %100‬فهــذا غيــر صحيــح والصحيــح بأننــي مــدان بنســبة ‪ %25‬وباقــي‬\n\n\n                                                                                    ‫‪272‬‬\n\f      ‫النســبة علــى مــورث موكلــي املدعــي وال مانــع لــدي مــن دفــع ‪ %25‬مــن‬\n      ‫الديــة واطلــب رد دعــوى املدعــي بالوكالــة يف باقــي النســبة هكــذا‬\n      ‫أجــاب وباالطــاع علــى املعاملــة علــى لفــة رقــم (‪ )27‬وهــو قــرار صــادر‬\n      ‫مــن احملكمــة اجلزئبــة برقــم ‪ 3311266‬يف ‪1433/1/5‬ه ـ واملتضمــن مــا‬\n      ‫نصــه (ثبــت لــدي إدانــة املدعــى عليــه ‪...‬بنســبة ‪)%25‬أ‪.‬ه ـ هــذا كمــا جرى‬\n      ‫االطــاع علــى لفــه رقــم (‪ )22‬وهــو خطــاب صــادر مــن مديــر إدارة مــرور‬\n      ‫الطائــف برقــم‪ 7/6/3164/7‬يف ‪1432/7/13‬ه ـ واملتضمــن بإدانــة‬\n      ‫الشــخص املصــدوم ‪...‬بنســبة‪ %75‬وباقــي النســبة ‪ %25‬تقــع علــى قائــد‬\n      ‫الســيارة هــذا كمــا جــرى االطــاع علــى تقريــر حــادث مــروري صــادر‬\n      ‫مــن قبــل ضابــط القضيــة النقيــب ‪...‬واملتضمــن يــدان الشــخص ‪ ...‬بنســبة‬\n      ‫‪ %75‬ويــدان قائــد الســيارة ‪...‬يف احلــادث بنســبة ‪ %25‬وبعــرض القــرار‬\n      ‫وكذلــك اخلطــاب وتقريــر احلــادث علــى املدعــي بالوكالــة قــال كل‬\n      ‫مــا جــاء فيهــا غيــر صحيــح واطلــب إعــادة املعاملــة للمــرور لدراســتها مــن‬\n      ‫جلنــة مختصــة لديهــم هكــذا قــرر وبعــرض ذلــك علــى املدعــى عليــه قــال‬\n      ‫كل مــا جــاء يف القــرار واخلطــاب والتقريــر صحيــح وال مانــع لــدي مــن‬\n      ‫إعــادة املعاملــة لدراســتها مــرة أخــرى هكــذا قــرر ثــم رفعــت اجللســة يف‬\n      ‫الســاعة الثانيــة عشــر ظهــرا وســيتم الكتابــة للمــرور لتزويدنــا بقــرار‬\n      ‫آخــر وحتــى الكتابــة وورود االجابــة وأفهــم املدعــي بالوكالــة بــأن عليــه‬\n      ‫إحضــار وكالــة عــن ‪...‬بصفتــه الولــي علــى القاصــرة ففهــم ذلــك وعليــه‬\n      ‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم حــرر يف ‪1433/06/24‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/02/19‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة التاســعة وفيهــا حضــر املدعــي بالوكالــة ‪......‬‬\n\n\n‫‪273‬‬\n\f‫واملدونــة اقامتــه ووكالتــه ســابقا ولــم يحضــر املدعــى عليــه ‪ ...‬ولــم‬\n‫يــرد إلينــا مــا يفيــد بتبليغــه عليــه وبنــاء علــى املــادة اخلامســة واخلمســن‬\n‫مــن نظــام املرافعــات الشــرعية فقــد قــررت الســير يف دعــوى املدعــي‬\n‫فجــرى ســؤال املدعــي هــل أحضــرت وكالــة أخــرى وقــد طلبــت منــك‬\n‫يف اجللســة املاضيــة فقــال نعــم ثــم أبــرز وكالــة صــادرة مــن رئاســة‬\n‫اجلهــاز القضائــي واليــة شــمال كردفــان بجمهوريــة الســودان مــن‬\n‫محكمــة األحــوال الشــخصية ‪ ...‬برقــم ‪ 2012/92‬واملصدقــة مــن وزارة‬\n‫العــدل برقــم ‪ 344146‬يف ‪1434/2/13‬ه ـ ومــن وزارة اخلارجيــة برقــم‬\n‫‪ 160751‬يف ‪1434/2/13‬ه ـ وتضمــن مــا نصــه حضــر ‪...‬الولــي الشــرعي‬\n‫علــى القاصــرة ‪ ......‬وقــام بتوكيــل ‪...‬والتــي تخولــه اســتالم جميــع‬\n‫االســتحقاقات وكل مــا يتعلــق بحقــوق املرحــوم ولــه حــق املقاضــاة ورفــع‬\n‫الدعــاوى وحضــور اجللســات هــذا كمــا ورد إلينــا خطــاب مــن مديــر‬\n‫إدارة مــرور محافظــة الطائــف برقــم ‪ 7/6/2189/7‬يف ‪1433/7/19‬ه ـ‬\n‫واملتضمــن مــا نصــه ( وأديــن الســائق ‪...‬يف احلــادث بنســبة ‪ %25‬والباقــي‬\n‫علــى الشــخص املصــدوم ) أ‪.‬ه ـ وبعــرض ذلــك علــى املدعــي وكالــة‬\n‫قــال كل مــا جــاء يف الوكالــة صحيــح وموكلــي مقتنعــن مــن هــذه‬\n‫النســبة هكــذا قــرر فجــرى ســؤاله هــل لديــك مــا ترغــب إضافتــه فقــال‬\n‫ليــس لــدي ســوى مــا ذكــرت هكــذا قــرر فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة ومبــا أن املدعــي قــد ذكــر يف دعــواه بإدانــة املدعــى‬\n‫عليــه يف احلــادث بنســبة ‪ %100‬ومبــا أن املدعــى عليــه قــد أقــر بوقــوع‬\n‫احلــادث ووفــاة مــورث موكلــي املدعــي هــذا احلاضــر وكذلــك إقــراره‬\n‫باخلطــأ بنســبة ‪ %25‬وملــا تضمنــه القــرار الصــادر مــن احملكمــة اجلزئيــة‬\n‫بالطائــف برقــم ‪ 3311266‬يف ‪1433/1/5‬ه ـ واملــدون ســابقا كمــا أن‬\n\n\n                                                                                        ‫‪274‬‬\n\f      ‫اخلطــا ب الصــادر مــن مديــر إدارة مــرور الطائــف واملــدون ســابقا تضمــن‬\n      ‫إدانــة املدعــى عليــه يف احلــادث بنســبة ‪ %25‬كمــا أن اخلطــاب األخيــر مــن‬\n      ‫مــرور الطائــف تضمــن نفــس اإلدانــة ونفــس التقريــر الســابق وملصادقــة‬\n      ‫املدعــي علــى ذلــك وال عــذر ملــن أقــر وقــد ذكــر ســماحة الشــيخ محمــد‬\n      ‫بــن ابراهيــم ال الشــيخ مفتــي اململكــة ورئيــس القضــاة بكتابــه فتــاوى‬\n      ‫ورســائل ‪ 353/11‬مــا نصــه ( القاتــل يتحملهــا ابتــداء ال العاقلــة وكان‬\n      ‫الواجــب يف اجلنايــة ممــا حتملــه العاقلــة وقد حضــر ملجلس احلكم اجلاني‬\n      ‫فهــل يحكــم بالواجــب علــى اجلانــي ثــم حتملــه العاقلــة أو يحكــم علــى‬\n      ‫العاقلــة مــع غيبتهــا ألن حضــور العاقلــة ومعرفتهــا مــن الصعــب؟ اجلــواب‪/‬‬\n      ‫ألوليــاء الــدم مطالبــة القاتــل ومحاكمتــه عنــد احلاكــم ليحكــم بثبــوت‬\n      ‫القتــل وليــس لهــم مطالبــة غيــره )أ‪.‬ه ـ وقــد ذكــر ابــن مفلــح رحمــه اهلل‬\n      ‫تعالــى يف كتابــه الفــروع ‪ 5/10‬مــا نصــه ( فائــدة مــا حتملــه العاقلــة هــل‬\n      ‫يجــب عليهــا ابتــداء أو علــى القاتــل ثــم حتملــه عنــه فيــه قــوالن ) أ‪.‬ه ـ وقــد‬\n      ‫ذكــر محمــد الكلبــي رحمــه اهلل تعالــى يف كتابــه القوانــن الفقهيــة‬\n      ‫‪ 257‬مــا نصــه ( فــرع جتــب علــى القاتــل اخلطــأ الكفــارة مــع الديــة ) أ‪.‬ه ـ‬\n      ‫جلميــع ذلــك فقــد ألزمــت املدعــى عليــه الغائــب عــن املجلــس الشــرعي‬\n      ‫‪...‬بــأن يدفــع لورثــة ‪...‬مبلــغ خمســة وســبعني ألــف ريــال ويكــون نصيــب‬\n      ‫األب الســدس زائــد الباقــي وهــو مبلــغ خمســة عشــر ألفــا وســتمائة‬\n      ‫وخمســة وعشــرين ريــاال ونصيــب األم مبلــغ اثنــا عشــر ألفــا وخمســمائة‬\n      ‫ريــال ونصيــب الزوجــة مبلــغ تســعة آالف وثالثمائــة وخمســة وســبعني‬\n      ‫ريــاال ونصيــب البنــت مبلــغ ســبعة وثالثــن ألفــا وخمســمائة ريــال وســوف‬\n      ‫اقــوم بدفــع هــذا املبلــغ لوكيــل الولــي حيــث أن القاصــرة ووليهــا خــارج‬\n      ‫البــاد كمــا أننــي ســوف أفهــم املدعــى عليــه بــأن عليــه كفــارة القتــل‬\n\n\n‫‪275‬‬\n\f‫خطــأ وهــي عتــق رقبــة فــإن لــم يجــد فصيــام شــهرين متتابعــن وبــه‬\n‫حكمــت وبعرضــه عليــه قنــع بــه وأفهمتــه بــأن هــذا احلكــم خاضــع‬\n‫لالســتئناف لوجــود القاصــرة كمــا أفهمتــه بــأن هــذا احلكــم حكــم‬\n‫حضــوري بالنســبة للمدعــى عليــه خاضــع لالســتئناف وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                          ‫‪ 1434/02/19‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم األربعــاء ‪ 1434/03/11‬ه ـ افتتحــت‬\n‫اجللســة الســاعة التاســعة والثلــث وفيهــا حضــر املدعــى عليــه ‪...‬واملدونــه‬\n‫هويتــه ســابقا وقــرر قائــا باننــي قــد اطلعــت علــى الصــك الصــادر مــن‬\n‫هــذه احملكمــة برقــم ‪ 3441472‬يف ‪1434/2/19‬ه ـ واملتضمــن الزامــي‬\n‫بدفــع مبلــغ خمســة وســبعني الــف ريــال وأنــا مقتنــع باحلكــم هكــذا‬\n‫قــرر فعليــه ولصــدور هــذا االقــرار مــن جائــز التصــرف فقــد ســقط حقــه‬\n‫يف تقــدمي الالئحــة وهــذا احلكــم خاضــع لالســتئناف لوجــود القاصــرة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                        ‫وســلم ‪ .‬حــرر يف ‪ 1434/03/11‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف ويف هــذا اليــوم اإلثنــن‪ 1434/05/06‬ه ـ افتتحــت اجللســة يف‬\n‫متــام الســاعة احلاديــة عشــر صباحــا وفيهــا وردت املعاملــة مــن محكمــة‬\n‫االســتئناف مبكــة املكرمــة برقــم ‪ 34626294‬يف ‪1434/04/22‬ه ـ‬\n‫وقــد جــرى تدقيــق احلكــم مــن الدائــرة اجلزائيــة السادســة وصــدر‬\n‫بشــأنه القــرار رقــم ‪ 34168222‬يف ‪1434/03/22‬ه ـ املــدون علــى ظهــر‬\n‫الصــك ونصــه (احلمــد هلل وحــد وبعــد فقــد اطلعنــا علــى هــذا الصــك‬\n‫رقــم ‪ 3441472‬وتاريــخ ‪1434/02/19‬ه ـ الصــادر مــن فضيلــة الشــيخ‬\n\n\n                                                                                   ‫‪276‬‬\n\f      ‫‪...‬واصدرنــا القــرار رقــم ‪ 34168222‬وتاريخ‪1434/03/22‬ه ـ املتضمــن‬\n      ‫املوافقــة علــى احلكــم عضــو ‪...‬ختمــه وتوقيعــه عضــو ‪...‬ختمــه توقيعــه‬\n      ‫رئيــس الدائــرة ‪...‬ختمــه وتوقيعه)أ‪.‬ه ـ وعليــه فقــد أمــرت بإحلــاق ذلــك‬\n      ‫بصكــه وســجله وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n      ‫آلــه وصحبــه وســلم حــرر يف ‪1434/05/06‬ه ـ الســاعة احلاديــة عشــر‬\n                                                                     ‫والربــع صباحــا ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم اإلثنــن ‪1434/06/26‬ه ـ افتتحت‬\n      ‫اجللســة يف متــام الســاعة الثامنــة وخمســة واربعــن دقيقــة صباحــا وفيهــا‬\n      ‫حضــر املدعــي وكالــة ‪......‬املدونــه هويتــه ووكالتــه ســابقا وقــد‬\n      ‫عــادت الينــا املعاملــة مــن مديــر إدارة مــرور محافظــة الطائــف برقــم‬\n      ‫‪ 7/6/1524/7‬يف ‪1434/06/18‬ه ـ واملقيــدة بهــذه احملكمــة برقــم‬\n      ‫‪ 341504121‬يف ‪1434/06/21‬ه ـ واملتضمنــه برفقــه الشــيك رقــم‬\n      ‫‪ 005327‬يف ‪2013/01/23‬م املســحوب علــى مصــرف الراجحــي املذيــل‬\n      ‫مببلغ خمســة وســبعني الف ريال باســم رئيس احملكمة العامة بالطائف‬\n      ‫لتســليمه للمســتفيد والتهميــش علــى صــك احلكــم بذلك وجرى تســليمه‬\n      ‫للمدعــي بالوكالــة ‪...‬وقــرر وهــو يف صحــة مــن عقلــه وجــواز أمــره قائــا‬\n      ‫بأنــه باســتالمي هــذا الشــيك املذيــل باملبلــغ احملكــوم ملوكلــي بالصــك‬\n      ‫رقــم ‪ 3441472‬يف ‪1434/02/19‬ه ـ لــم يعــد ملوكلــي أي دعــوى أو‬\n      ‫مطالبــة ضــد املدعــى عليــه ‪...‬وتعتبــر دعواهــم ضــده منتهيــة هكــذا قــرر‬\n      ‫فبنــاء علــى اقــراره واســتالمه وحيــث إن وكالتــه تخولــه حــق االســتالم‬\n      ‫والتوقيــع توكيــا عامــا فقــد ثبــت لــدي وأمــرت بالتهميــش علــى صــك‬\n      ‫احلكــم وســجله بذلــك وعليــه جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/06/26‬ه ـ‬\n\n\n‫‪277‬‬\n\f                                                ‫الســاعة التاســعة صباحــا ‪.‬‬\n           ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة اجلزائيــة السادســة‬\n‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا اإلطــاع‬\n‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالطائــف‬\n‫املســاعد برقــم (‪ )34/626294‬وتاريــخ (‪1434/3/11‬هــ) املرفــق بهــا‬\n‫الصــك الصــادر مــن فضيلــة الشــيخ‪،... /‬القاضــي باحملكمــة العامــة‬\n‫بالطائــف برقــم (‪ )3441472‬وتاريــخ (‪1434/2/19‬هــ) املتضمــن دعــوى‬\n‫ورثــة ‪...‬ضــد‪... /‬يف ديــة حــادث ‪،‬احملكــوم فيــه مبــا دون باطنــه ‪،‬‬\n‫وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل‬\n     ‫املوفق‪،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                               ‫‪278‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":269,"source_page_end":278,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"279cf34cae24a94ff27feed045aa875061fc3927946a986f9b6cc131c6fefcb7","normalized_text_hash":"c64d8b59237c74e10a26c322854815a148906c21a660e3f777852e3e567e16ea","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p269-3441472"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"81fdf3bd-9eb0-5453-ba66-f5ada526a345","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية متوفى -حادث مروري -املطالبة بعدد من الديات -إقرار املدعى عليه -يحكم على الغائب املمتنع عن احلضور ملجلس القضاء -دية املرأة على النصف من دية الرجل -احلكم بدفع دية","document_number":"33475561","case_number":"32334212","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/22","year":"1434","subject":"دية متوفى -حادث مروري -املطالبة بعدد من الديات -إقرار املدعى عليه -يحكم على الغائب املمتنع عن احلضور ملجلس القضاء -دية املرأة على النصف من دية الرجل -احلكم بدفع دية","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/12/22 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33475561 :‬‬\n                          ‫َر ْق ُم الدعوى‪32334212 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3426009‬تاريخه‪1434/1/28 :‬ه‬\n\n\n       ‫ديــة متوفــى ‪ -‬حــادث مــروري ‪ -‬املطالبــة بعــدد مــن الديــات ‪ -‬إقــرار‬\n       ‫املدعــى عليــه ‪ -‬يحكــم علــى الغائــب املمتنــع عــن احلضــور ملجلــس‬\n       ‫القضــاء ‪ -‬ديــة املــرأة علــى النصــف مــن ديــة الرجــل ‪ -‬احلكــم بدفــع ديــة‬\n                                                                         ‫قتــل اخلطــأ‪.‬‬\n\n\n\n\n             ‫‪ .1‬ما ذكره أهل العلم أن دية املرأة على النصف من دية الرجل ‪.‬‬\n       ‫‪ .2‬مــا ذكــره أهــل العلــم بأنــه يحكــم علــى الغائــب املمتنــع عــن احلضــور‬\n                                                                    ‫ملجلــس القضاء ‪.‬‬\n       ‫‪ .3‬األمــر الســامي رقــم ‪ 43108‬يف ‪1432/10/2‬ه ـ بشــأن حتديــد ديــة‬\n       ‫قتــل اخلطــأ املعمــم مــن قبــل معالــي وزيــر العــدل برقــم ‪/13‬ت‪4363/‬‬\n                                                                 ‫يف ‪1432/10/7‬ه ـ ‪.‬‬\n\n\n\n       ‫ادعــى املدعــي بالوكالــة عــن جميــع ورثــة املتوفــاة ‪ ...‬وعــن جميــع ورثــة‬\n       ‫املتوفــاة ‪ ...‬وجميــع الــوكاالت والصكــوك مصــادق عليهــا مــن جميــع‬\n       ‫اجلهــات الرســمية ذات العالقــة ـ كمــا حضــر املدعــي بالوكالــة عــن‬\n       ‫جميــع ورثــة املتوفــى ‪ ...‬طلــب املدعــون احلكــم لهــم بديــة قتــل اخلطــأ‬\n       ‫ملورثــي موكليهــم ـ لــم يحضــر املدعــى عليــه اجللســة ‪ ،‬مــع تبليغــه‬\n\n‫‪233‬‬\n\f‫مبوعدهــا‪ ،‬حيــث تبلــغ لشــخصه ـ مت اإلطــاع علــى القــرار الشــرعي‬\n‫الصــادر مــن احملكمــة اجلزائيــة املتضمــن إدانــة املدعــى عليه مبســئوليته‬\n‫عــن احلــادث بنســبة ‪ % 100‬وقنــع املدعــى عليــه بهــذا احلكــم ـ مت االطــاع‬\n‫علــى صكــوك حصــر الورثــة ـ تبليــغ املدعــى عليــه لشــخصه مرتــن ولــم‬\n‫يحضــر ‪ ،‬وقــد ذكــر أهــل العلــم أنــه يحكــم علــى الغائــب املمتنــع عــن‬\n‫احلضــور ملجلــس القضــاء ـ ذكــر أهــل العلــم أن ديــة املــرأة علــى النصــف‬\n‫مــن ديــة الرجــل ـ مت االطــاع علــى األمــر الســامي املتضمــن تعديــل ديــة‬\n‫قتــل اخلطــأ إلــى ‪ 300,000‬ألــف ريــال ـ احلكــم علــى املدعــى عليــه بــأن‬\n‫يدفــع لورثــة ‪ ...‬مبلغـ ًا وقــدره ‪ 300,000‬ألــف ريــال ـ احلكــم علــى املدعــى‬\n‫عليــه بــأن يدفــع لورثــة ‪ ...‬مبلغـ ًا وقــدره ‪ 150,000‬ألف ريــال ـ احلكم على‬\n‫املدعــى عليــه ـ بــأن يدفــع لورثــة ‪ ...‬مبلغ ـ ًا وقــدره ‪ 150,000‬ألــف ريــال ـ‬\n‫يقســم هــذا املــال حســب القســمة الشــرعية ـ قــرر احلاضــرون قناعتهــم‬\n‫باحلكــم‪ ،‬األمــر بتزويــد املدعــى عليــه بصــورة مــن احلكــم لتقــدمي مــا‬\n          ‫لديــه مــن اعتــراض ـ صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامة مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 32334212‬وتاريــخ ‪1432/08/08‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 321010162‬وتاريــخ ‪ 1432/08/08‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافــق‪ 1433/12/01‬ه ـ افتتحــت اجللســة الســاعة ‪09،15‬‬\n‫وفيهــا حضــر ‪ ...‬ســوري اجلنســية يحمــل إقامــة رقــم ‪ ...‬الوكيــل عــن‬\n‫‪ ...‬ســوري اجلنســية مبوجــب الهويــة الوطنيــة الســورية رقــم ‪ ...‬مبوجــب‬\n\n                                                                                      ‫‪234‬‬\n\f      ‫الوكالــة الصــادرة مــن كاتــب العــدل الثانــي بدمشــق برقــم ‪ 15927‬يف‬\n      ‫‪ 30‬كانــون األول ‪2010‬م واملصدقــة مــن اجلهــات املعتمــدة وآخرهــا فــرع‬\n      ‫وزارة العــدل مبكــة برقــم ‪ 4566‬يف ‪1432/8/8‬ه ـ والوكيــل عــن ‪...‬‬\n      ‫ســورية اجلنســية حتمــل هويــة وطنيــة ســورية رقــم ‪ ...‬و‪ ...‬ســورية اجلنســية‬\n      ‫حتمــل هويــة وطنيــة ســورية رقــم ‪ ...‬و‪ ...‬ســورية اجلنســية حتمــل هويــة‬\n      ‫ســورية رقــم ‪ ...‬و‪ ...‬ســورية اجلنســية حتمــل هويــة وطنيــة ســورية رقــم ‪ ...‬و‪...‬‬\n      ‫ســورية اجلنســية حتمــل هويــة وطنيــة ســورية رقــم ‪ ...‬و‪ ...‬ســورية اجلنســية‬\n      ‫حتمــل هويــة وطنيــة ســورية رقــم ‪ ...‬و‪ ...‬ســورية اجلنســية حتمــل هويــة‬\n      ‫وطنيــة ســورية رقــم ‪ ...‬و‪ ...‬ســوري اجلنســية يحمــل هويــة وطنيــة ســورية‬\n      ‫رقم ‪ ... ...‬و‪ ...‬ســوري اجلنســية يحمل هوية وطنية ســورية رقم ‪ ...‬مبوجب‬\n      ‫الوكالــة الصــادرة مــن كاتــب العــدل الثانــي بدمشــق برقــم ‪ 15806‬يف‬\n      ‫‪ 28‬كانــون األول ‪2010‬م واملصــدق مــن اجلهــات املعتمــدة وآخرهــا فــرع‬\n      ‫وزارة العــدل مبكــة برقــم ‪ 4567‬يف ‪1432/8/10‬ه ـ كمــا حضــر ‪...‬‬\n      ‫ســعودي بالســجل املدنــي رقــم ‪ ...‬الوكيــل عــن ‪ ...‬ســعودية اجلنســية‬\n      ‫بالســجل املدنــي رقــم ‪ ...‬أصالــة عــن نفســها وبواليتهــا علــى أوالدهــا ‪...‬‬\n      ‫و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬أوالد ‪ ...‬مبوجــب صــك الواليــة‬\n      ‫رقــم ‪ 44‬يف ‪1431/9/18‬ه ـ الصــادر مــن محكمــة العرضيــة اجلنوبيــة‬\n      ‫و‪ ...‬ســعودي بالســجل املدنــي رقــم ‪ ...‬و‪ ...‬ســعودية بالســجل املدنــي ‪...‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كاتــب عــدل العرضيــة اجلنوبيــة برقــم‬\n      ‫‪ 20‬يف ‪1431/10/9‬ه ـ املجلــد ‪ 604‬وادعيــا علــى الغائــب عــن مجلــس‬\n      ‫القضــاء ‪ ...‬هــذا وقــد تبلــغ املدعــى عليــه لشــخصه للجلســة التــي حــدد‬\n      ‫لهــا موعــد يف يــوم الثالثــاء املوافــق ‪1433/11/30‬ه ـ ولكــن نظــرا‬\n      ‫العتــذاري عــن حضورهــا لظــرف صحــي فقــد أجلــت لهــذا اليــوم‬\n\n\n‫‪235‬‬\n\f‫األربعــاء املوافــق ‪1433/12/1‬ه ـ قائلــن يف دعواهــم لقــد وقــع حــادث‬\n‫تصــادم بطريــق مكــة جــدة الســريع مقابــل مــدارس ‪ ...‬يف ‪1431/9/8‬ه ـ‬\n‫بــن ســيارتني األولــى مــن نــوع ‪ ...‬رقــم اللوحــة (‪ )...‬قيــادة املدعــى عليــه‬\n‫والســيارة الثانيــة مــن نــوع ‪ ...‬رقــم اللوحــة (‪ ) ...‬قيــادة مــورث موكلــي‬\n‫‪ ...‬وقــد جنــم عــن احلــادث وفــاة ‪ ...‬وكل مــن ‪ ...‬و‪ ...‬بنــت ‪ ...‬هــذا وقــد‬\n‫أديــن املدعــى عليــه بنســبة ‪ %100‬بكامــل املســؤولية عــن احلــادث وذلــك‬\n‫مبوجــب القــرار الصــادر مــن احملكمــة اجلزائيــة مبكــة املكرمــة‬\n‫برقــم ‪ 2/1‬يف ‪1432/2/7‬ه ـ نطلــب احلكــم علــى املدعــى عليــه أن‬\n‫يدفــع ديــة قتــل اخلطــأ ملورثــي موكلينــا كل علــى حــدا هــذه دعوانــا‬\n‫فجــرى االطــاع علــى القــرار املشــار إليــه أعــاه فوجدتــه كمــا ذكــر‬\n‫ومنتهــي بقناعــة املدعــى عليــه بهــذه النســبة كمــا جــرى االطــاع‬\n‫علــى الصــك الصــادر مــن احملكمــة العامــة بالعرضيــة اجلنوبيــة برقــم‬\n‫‪ 44‬يف ‪1431/9/18‬ه ـ والــذي يثبــت وفــاة ‪ ...‬وانحصــار إرثــه يف كل‬\n‫مــن والدتــه ‪ ... ...‬ويف زوجتــه ‪ ...‬ويف أوالده ‪ ...‬البالــغ والقاصريــن كل‬\n‫مــن ‪ ...‬املولــودة يف ‪1417/12/18‬ه ـ و‪ ...‬املولــودة يف ‪1418/11/26‬ه ـ‬\n‫و‪ ...‬املولــودة يف ‪1420/7/10‬ه ـ و‪ ...‬املولــودة يف ‪1422/11/19‬ه ـ و‪...‬‬\n‫املولــود ‪1424/9/26‬ه ـ و‪ ...‬املولــود يف ‪1426/4/27‬ه ـ و‪ ...‬املولــودة‬\n‫يف ‪1427/12/19‬ه ـ و‪ ...‬املولــودة يف ‪1429/7/22‬ه ـ و‪ ...‬املولــودة يف‬\n‫‪1431/6/18‬ه ـ و‪ ...‬املولــودة يف ‪1431/6/18‬ه ـ كمــا جــرى االطــاع‬\n‫علــى صــك الواليــة الصــادر مــن احملكمــة العامــة بالعرضيــة اجلنوبيــة‬\n‫برقــم ‪ 14‬يف ‪1431/9/18‬ه ـ والــذي فيــه أن ‪ ...‬ســعودية بالســجل املدنــي‬\n‫رقــم ‪ ...‬هــي الوليــة علــى أوالدهــا القصــر كمــا جــرى االطــاع علــى‬\n‫وثيقــة حصــر اإلرث الشــرعي الصــادر مــن محكمــة قطنــا الشــرعية‬\n\n\n                                                                                      ‫‪236‬‬\n\f      ‫برقــم ‪ 199‬يف ‪1432/1/3‬ه ـ واملصــدق مــن اجلهــات املعتمــدة وآخرهــا‬\n      ‫فــرع وزارة العــدل برقــم ‪ 4564‬يف ‪1432/8/10‬ه ـ والــذي يثبــت وفــاة‬\n      ‫‪ ... ...‬وانحصــار إرثهــا يف ‪ ...‬و‪ ...‬و‪ ...‬و‪ ... ...‬و‪ ...‬أوالد ‪ ...‬كمــا جــرى‬\n      ‫االطــاع علــى وثيقــة حصــر اإلرث الشــرعي الصــادرة مــن محكمــة‬\n      ‫الصنمــن برقــم ‪ 415‬يف ‪1432/1/21‬ه ـ والــذي يثبــت وفــاة ‪ ...‬وانحصــار‬\n      ‫إرثهــا يف أوالدهــا ‪ ...‬و‪ ...‬و‪ ... ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪...‬‬\n      ‫أوالد ‪ ...‬واملصــدق مــن اجلهــات املعتمــدة وآخرهــا فــرع وزارة العــدل برقــم‬\n      ‫‪ 4963‬يف ‪1432/8/10‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫وبنــاء علــى مــا جــاء يف القــرار الصــادر مــن احملكمــة اجلزائيــة برقــم ‪2/1‬‬\n      ‫يف ‪1432/1/7‬ه ـ مــن إثبــات إدانــة املدعــى عليــه بنســبة احلــادث ‪%100‬‬\n      ‫وقناعتــه بهــذه النســبة وملــا ذكــره أهــل العلــم رحمهــم اهلل تعالــى بأنــه‬\n      ‫يحكــم علــى الغائــب املمتنــع عــن احلضــور ملجلــس القضــاء ولتبلغ املدعى‬\n      ‫عليــه لشــخصه مرتــن ولــم يحضــر وملــا ذكــره أهــل العلــم رحمهــم اهلل‬\n      ‫مــن أن ديــة املــرأة علــى النصــف مــن ديــة الرجــل وبنــاء علــى األمر الســامي‬\n      ‫رقــم ‪ 43108‬يف ‪1432/10/2‬ه ـ بشــأن حتديــد ديــة قتــل اخلطــأ املعمــم‬\n      ‫مــن معالــي وزيــر العــدل برقــم ‪/13‬ت‪ 4363/‬يف ‪1432/10/7‬ه ـ لذلــك‬\n      ‫كلــه فقــد حكمــت علــى املدعــى عليــه أن يدفــع لورثــة ‪ ...‬مبلغــا وقــدره‬\n      ‫ثالثمائــة ألــف ريــال ديــة قتــل اخلطــأ تقســم علــى الورثــة حســب الفريضــة‬\n      ‫الشــرعية كمــا حكمــت عليــه أن يدفــع لورثــة ‪ ...‬مبلغــا وقــدره مائــة‬\n      ‫وخمســون ألــف ريــال ديــة قتــل اخلطــأ تقســم علــى الورثــة حســب الفريضــة‬\n      ‫الشــرعية كمــا حكمــت عليــه أن يدفــع لورثــة ‪ ...‬مبلغــا وقــدره مائــة‬\n      ‫وخمســون ألــف ريــال ديــة قتــل اخلطــأ تقســم علــى الورثــة حســب الفريضــة‬\n      ‫الشــرعية وبعــرض احلكــم علــى احلاضريــن قــررا القناعة وأمــرت بتزويد‬\n\n\n‫‪237‬‬\n\f‫املدعــى عليــه بنســخة مــن صــك احلكــم لتقــدمي مــا لديــه مــن اعتــراض مع‬\n‫إفهامــه أن لــه ثالثــن يومــا مــن تاريــخ اســتالمه لنســخة احلكــم لتقــدمي‬\n‫االعتــراض وأنــه إذا لــم يقــدم اعتراضــه خــال هــذه املــدة ســقط حقــه‬\n‫يف االســتئناف واكتســب احلكــم القطعيــة وبــاهلل التوفيــق صلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/12/01‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم‪32/1010162‬‬\n‫وتاريــخ‪ 1434/1/19‬ه ـ ـ املرفــق بهــا الصــك رقــم‪ 33475561‬وتاريــخ‬\n‫‪1433/12/22‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ... /‬القاضــي باحملكمــة‬\n‫العامــة مبكــة املكرمــة املتضمــن دعــوى ورثــة ‪ ... /‬ورفقــاه ضــد الغائب‬\n‫عــن مجلــس القضــاء ‪ ... /‬ســعودي اجلنســية يف مطالبــة بديــة متــويف‬\n‫بحــادث مــروري احملكــوم فيــه مبــا دون بباطــن الصــك ‪ ،‬وبدراســة‬\n‫الصــك وصــورة ضبطــه قررنــا املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق‬\n              ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪238‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":233,"source_page_end":238,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4ca2604f172ca039228fa7beddc0ca8b2214f73c22c2a76dc066a1488d08597b","normalized_text_hash":"dd0951306f67bc37be45f209750364228ba1b4b505e904825b0479cfb364a3e6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p233-33475561"},{"id":"322e0f58-f926-56a7-b9ed-c812191fb0bf","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية متوفى -حادث مروري دهس -مطالبة بدية قتل اخلطأ بحسب نسبة اخلطأ -إقرار املدعى عليه -العذر ملن أقر -احلكم على املدعى عليه بدفع الدية مقابل نسبة اخلطأ التي عليه .","document_number":"34175065","case_number":"32421651","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":"الدائرة اجلزائية اخلامسة برقم 33140741يف تاريخ 1433/03/19ه","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/29","year":"1434","subject":"دية متوفى -حادث مروري دهس -مطالبة بدية قتل اخلطأ بحسب نسبة اخلطأ -إقرار املدعى عليه -العذر ملن أقر -احلكم على املدعى عليه بدفع الدية مقابل نسبة اخلطأ التي عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/29 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34175065 :‬‬\n                         ‫َر ْق ُم الدعوى‪32421651 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34282939‬تاريخه‪1434/7/30 :‬هـ‬\n\n\n      ‫ديــة متوفــى ‪ -‬حــادث مــروري دهــس ‪ -‬مطالبــة بديــة قتــل اخلطــأ‬\n      ‫بحســب نســبة اخلطــأ ‪ -‬إقــرار املدعــى عليــه ‪ -‬العــذر ملــن أقــر ‪ -‬احلكــم‬\n        ‫علــى املدعــى عليــه بدفــع الديــة مقابــل نســبة اخلطــأ التــي عليــه ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قــال ابــن قدامــة ـ رحمــه اهلل ـ يف املغنــي ( ‪ ( ) 339/9‬واألصــل يف‬\n      ‫وجــوب الديــة والكفــارة قولــه تعالــى ‪ ( :‬ومــن قتــل مؤمنـ ًا فتحريــر رقبــة‬\n                             ‫مؤمنــة وديــة مســلمة إلــى أهلــه إال أن يصدقــوا ) ‪.‬‬\n                                                        ‫‪ .2‬قاعدة ( ال عذر ملن أقر )‬\n      ‫‪ .3‬قــرار الهيئــة باحملكمــة العليــا برقــم ‪ 2‬يف ‪1431/7/14‬ه ـ املوافــق عليــه‬\n      ‫باألمــر الســامي رقــم ‪ 43108‬يف ‪1432/10/2‬ه ـ املتضمــن أن ديــة قتــل‬\n                                       ‫اخلطــأ هــي ثالثمائــة ألــف ريــال ســعودي ‪.‬‬\n\n\n\n      ‫ادعــى املدعــي بالوكالــة عــن ورثــة امليــت مبوجــب الــوكاالت وصــك‬\n      ‫حصــر الورثــة والواليــة املصــادق عليهــا مــن اجلهات الرســمية ذات العالقة‬\n      ‫‪ ،‬لوحــظ أن األم ذكــرت أنهــا وليــة علــى ابنتيهــا ‪ ...‬و‪ ...‬وهمــا ليســتا‬\n      ‫قاصرتــن بــل همــا بالغتــان فطلــب مــن املدعــي وكالــة تعديــل صــك‬\n      ‫الواليــة فأفــاد أن النظــام يف القانــون املصــري يعتبــر أن الرشــد يف املــال‬\n\n‫‪239‬‬\n\f‫هــو إحــدى وعشــرون ســنة ميالديــة فتــم مخاطبــة محكمــة االســتئناف‬\n‫فوجهــت مبخاطبــة القنصليــة ‪ ،‬فتمــت الكتابــة للقنصليــة املصريــة ‪،‬‬\n‫وردت اإلجابــة املتضمنــة أن القانــون املصــري يعتبــر أن الرشــد يف املــال‬\n‫هــو إحــدى وعشــرون ســنة ميالديــة فقــرر القاضــي ســماع الدعــوى ‪،‬‬\n‫طلــب املدعــي وكالــة احلكــم علــى املدعــى عليــه بتســليمه ‪% 25‬مــن‬\n‫ديــة قتــل اخلطــأ ‪ ،‬بعــرض دعــوى املدعــي وكالــة علــى املدعــى عليــه‬\n‫صــادق علــى مــا جــاء بدعــوى املدعــي وكالــة ‪ ،‬مت االطــاع علــى أوراق‬\n‫املعاملــة فوجــد أنهــا مطابقــة ملــا جــاء بدعــوى املدعــي وكالــة ‪ ،‬احلكــم‬\n‫علــى املدعــى عليــه بتســليم ربــع الديــة للمدعــي وكالــة وهــو مبلــغ‬\n‫وقــدره خمســة وســبعون ألــف ريــال ‪ ،‬مت قســمة املبلــغ حســب األنصبــة‬\n‫الشــرعية ‪ ،‬مت إفهــام املدعــى عليــه بالكفــارة ‪ ،‬قــرر املدعــي وكالــة‬\n‫قناعتــه باحلكــم ‪ ،‬وقــرر املدعــى عليــه اعتراضــه علــى احلكــم بالئحــة‬\n                ‫اعتراضيــة ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف املســاعد برقــم ‪ 32421651‬وتاريخ‪1432/9/21‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 321218265‬وتاريــخ ‪ 1432/9/21‬ه ـ‬\n‫ففــي يــوم اإلثنــن املوافــق ‪1433/2/2‬ه ـ حضــر ‪........‬مصــري اجلنســية‬\n‫مبوجــب جــواز الســفر رقــم ‪........‬بصفتــه وكيــا عــن املدعــن وهــم ورثــة‬\n‫املتوفــى ‪........‬وذلــك مبوجــب حصــر الورثــة الصــادر مــن مصلحــة الشــهر‬\n‫العقــاري برقــم ‪........‬وهــم والــده ‪........‬وزوجتيــه ‪........‬و‪ ........‬وأوالده ‪........‬‬\n\n                                                                                              ‫‪240‬‬\n\f      ‫و‪........‬و‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬وذلــك مبوجــب وكالتــه عــن‬\n      ‫ابنيــي املتوفــى ‪........‬و‪........‬الصــادرة مــن جمهوريــة مصــر العربيــة برقــم‬\n      ‫‪........‬يف ‪2011/7/7‬م والتــي تخولــه حــق الترافــع يف جميــع القضايا وحق‬\n      ‫اإلقــرار واإلنــكار وبوكالتــه عــن إبــن املتوفــى ‪........‬مبوجــب الوكالــة‬\n      ‫الصــادر مــن جمهوريــة مصــر العربيــة برقــم ‪ ........‬يف ‪2011/5/25‬م‬\n      ‫والتــي تخولــه حــق الترافــع يف جميــع القضايــا وحــق اإلقــرار واإلنــكار‬\n      ‫ومبوجــب وكالتــه عــن والــد املتوفــى ‪........‬وعــن زوجتــه ‪........‬وعــن زوجته‬\n      ‫‪........‬أصالــة عــن نفســها وبواليتهــا عــن أوالدهــا القصــر ‪........‬املولــود يف‬\n      ‫‪1997/6/1‬م و‪ ........‬املولود ‪ 1999/3/21‬وقد ذكر يف نفس التوكيل‬\n      ‫أنهــا وليــة علــى ابنتيهــا ‪........‬املولــودة يف ‪1992/2/8‬م و‪ ........‬املولــودة يف‬\n      ‫‪ 1994/4/8‬م وهمــا ليســتا قاصرتــن بــل همــا بالغتــن لــذا جــرى إفهــام‬\n      ‫الوكيــل بأنــه يلزمــه إحضــار وكالــه عــن املذكورتــن الســتكمال‬\n      ‫نظــر دعــواه وحتــى يكمــل املطلــوب جــرى رفــع اجللســة وتأجيلهــا حتــى‬\n                                                                                 ‫يتــم ذلــك‬\n      ‫ويف جلســة آخــرى يف يــوم األحــد املوافــق‪ 1434/02/24‬هـ حضر املدعي‬\n      ‫وكالــة وأمــا املدعــى عليــه فلــم يحضــر وقــد تبلــغ لشــخصه وقــد ســبق‬\n      ‫وأن قــدم املدعــي وكالــة اســتدعاء أحيــل إلينــا بشــرح رئيــس احملكمــة‬\n      ‫برقــم ‪ 33239503‬يف تاريــخ ‪1433/02/06‬ه ـ ويتضمــن أن البنتــن‬\n      ‫اللتــن أفهمتــه بــأن يحضــر وكالــة عنهــا لكونهمــا بالغتــن يعتبــران‬\n      ‫يف ( القانــون املصــري ) قاصرتــن ألنهمــا دون ســن ( واحــد وعشــرين‬\n      ‫ســنة ) وال يســمح النظــام بــأن يــوكال ألنهمــا ال زاال حتــت الواليــة مــن‬\n      ‫قبــل والدتهــم فجــرت مخاطبــة محكمــة االســتئناف مبكــة املكرمــة‬\n           ‫باخلطــاب رقــم ‪ 321474714‬يف تاريــخ ‪1433/03/07‬ه ـ واملتضمــن‬\n\n\n‫‪241‬‬\n\f‫( طلــب التوجيــه حيــال مــا ذكــره املدعي وكالة من أن النظام ال يســمح‬\n‫ملــن هــم دون ســن الواحــدة والعشــرون بالتوكيــل ) أ‪.‬هــ‪ .‬فوردنــا خطابهــم‬\n‫رقــم ‪ 33490336‬يف تاريــخ ‪1433/03/22‬ه ـ واملعطــوف علــى قــرار‬\n‫الدائــرة اجلزائيــة اخلامســة برقــم ‪ 33140741‬يف تاريــخ ‪1433/03/19‬ه ـ‬\n‫واملتضمــن ( فعليــه واحلــال مــا ذكــر فيستفســر مــن الســفارة املصريــة‬\n‫عــن صحــة ذلــك ) أ‪.‬هــ‪ .‬عليــه فقــد جــرت الكتابــة للقنصليــة املصريــة‬\n‫بالطريقــة الرســمية عــن طريــق احملافظــة التــي كتبــت بدورهــا لفــرع‬\n‫وزارة اخلارجيــة مبكــة املكرمــة فوردنــا خطابهــم رقــم ‪138/3/2/21‬‬\n‫يف تاريــخ ‪1433/07/13‬ه ـ واملتضمــن ( أفــادت القنصليــة املصريــة‬\n‫بأنــه إذا كان موضــوع الدعــوى حقــوق ماليــه ألبنــاء املتوفــى املذكــور‬\n‫مســتحقة لهــم بامليــراث عــن والدهــم فــإن ســن الرشــد طبقــا للقانــون‬\n‫املصــري هــو احــدى وعشــرون ســنة ميالديــة ) أ‪.‬هــ‪ .‬عليــه قــررت ســماع‬\n‫دعــوى املدعــي وكالــة فادعــى قائــا لقــد حصــل حــادث مــروري ملــورث‬\n‫موكليــي نتــج عنــه وفاتــه بتاريــخ ‪1431/10/25‬ه ـ وقــد أديــن املدعــى‬\n‫عليــه بنســبة خمســة وعشــرون فاملائــة وصــدر عليــه بذلــك صــك مــن‬\n‫احملكمــة اجلزئيــة برقــم ‪ 3226226‬يف تاريــخ ‪1432/02/14‬ه ـ أطلــب‬\n‫احلكــم علــى املدعــى عليــه بــأن يدفــع ‪ %25‬مــن ديــة قتــل اخلطــأ ملوكليــي‬\n                                                                    ‫هــذه دعــواي‬\n‫ويف جلسة آخرى يف يوم السبت املوافق‪ 1434/03/28‬هـ حضر املدعي‬\n‫وكالــة وحضــر حلضــوره ‪........‬ســعودي اجلنســية مبوجــب ســجله املدنــي‬\n‫رقــم ‪........‬ثــم جــرى تــاوة مــا ســبق ضبطــه علــى املدعــى عليــه فصــادق‬\n‫عليــه ثــم جــرى عــرض دعــوى املدعــي علــى املدعــى عليــه فأجــاب قائــا‬\n‫مــا ذكــره املدعــي وكالــة يف دعــواه كلــه صحيــح جملــة وتفصيــا فقــد‬\n\n\n                                                                                    ‫‪242‬‬\n\f      ‫تســببت يف وفــاة مــورث موكليــه وكانــت نســبة اإلدانــه علي هي خمســة‬\n      ‫وعشــرون يف املائــه (‪ )%25‬هكــذا أجــاب ثــم جــرى اإلطــاع علــى أوراق‬\n      ‫املعاملــة فوجــدت مطابقــة ملــا جــاء يف دعــوى املدعــي وكالــة فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه مبــا جــاء يف دعــوى‬\n      ‫املدعــي وكالــة وألنــه ال عــذر ملــن أقــر وملــا تضمنــه القــرار املشــار إليــه‬\n      ‫بعاليــه مــن أن نســبة اخلطــأ يف احلــادث علــى املدعــى عليــه هــي (‪ )%25‬وملــا‬\n      ‫جــاء يف قــرار الهيئــة العامــة للمحكمــة العليــا رقــم ‪ 2‬يف ‪1431/7/14‬ه ـ‬\n      ‫املوافــق عليــه باألمــر الســامي رقــم ‪ 43108‬يف ‪1432/10/2‬ه ـ املتضمــن‬\n      ‫يف الفقــرة الثانيــة منــه أن ديــة اخلطــأ هــي ثالثمائــة ألــف ريــال ســعودي‬\n      ‫وألن النســبة املشــار إليهــا يف حــق املدعــى عليــه متثــل ربــع ديــة قتــل‬\n      ‫اخلطــأ يقــول ابــن قدامــه يف املغنــي ‪ ( 339/9‬واألصــل يف وجــوب الديــة‬\n      ‫والكفــارة قولــه تعالــى ( ومــن قتــل مؤمنــا خطــأ فتحريــر رقبــة مؤمنــة‬\n      ‫وديــة مســلمة إلــى أهلــه إال أن يصدقــوا) لذلــك كلــه فقــد حكمــت‬\n      ‫علــى املدعــى عليــه بدفــع مبلــغ وقــدره خمســة ســبعون ألــف ريــال بحيــث‬\n      ‫يكــون نصيــب األب الســدس وميثــل مبلــغ وقــدره اثنــا عشــر ألــف‬\n      ‫وخمســمائة ريــال ونصيــب كل زوجــه مبلــغ وقــدره أربعــة أالف وســتمائه‬\n      ‫وســبعة وثمانــون ريــال وخمســون هللــه والباقــي يقســم للذكــر مثــل حــظ‬\n      ‫األنثيــن فيكــون نصيــب كل ابــن مــن األبنــاء الذكــور تســعة آالف‬\n      ‫وســتمائه وتســعة وخمســون ريــال وتســعه هلــات ونصيــب كل بنــت‬\n      ‫أربعــة آالف وثمامنائــه وتســعة وعشــرون ريــاال وخمســة وخمســون هللــه‬\n      ‫وألنــه ســبق اإلفهــام بالكفــارة كمــا ذكــر يف قــرار احملكمــة اجلزئيــة‬\n      ‫املشــار إليــه آنفــا فــا داعــي لتكــراره وبعــرض احلكــم علــى الطرفــن‬\n      ‫قــرر املدعــي وكالــة القناعــة بــه وأمــا املدعــى عليــه لــم يقتنــع بــه ورغــب‬\n\n\n‫‪243‬‬\n\f‫يف تقــدمي الئحــة اعتراضيــة فجــرى تســليمه نســخة مــن صــك احلكــم‬\n‫يف اجللســة وأفهــم بــأن لــه ثالثــون يومــا مــن تاريــخ هــذا اليــوم لتقــدمي مــا‬\n‫لديــه مــن اعتــراض فــإن لــم يفعــل ســقط حقــه يف االعتــراض واكتســب‬\n‫احلكــم الصفــة القطعيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪ 1434/03/28‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف ففــي يــوم األربعــاء املوافق‪1434/05/08‬ه ـ وردتنــا الالئحــة‬\n‫اإلعتراضيــة املقدمــة مــن ‪........‬واحملالــة مــن رئيــس احملكمــة برقــم‬\n‫‪341021890‬يف ‪1434/4/27‬ه ـ وهــي ورقتــن وكان تقدميهــا خــال‬\n‫املــدة احملــددة وباإلطــاع عليهــا لــم أجــد بهــا مــا يؤثــر علــى ماحكمــت‬\n‫بــه أو يدعــو للعــدول عنــه وعليــه ســوف يجــري بعــث كامــل املعاملــة‬\n‫ومرفقاتهــا إلــى محكمــة اإلســتئناف كاملتبــع وبــاهلل التوفيــق ‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                ‫‪1434/05/08‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جرى منا نحن قضاة الدائرة اجلزائية اخلامســة مبحكمة اإلســتئناف يف‬\n‫منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الواردة مــن فضيلة رئيس‬\n‫احملكمــة العامــة بالطائــف برقــم ‪332044454‬وتاريــخ ‪1434/7/17‬ه ـ‬\n‫املرفــق بهــا الصــك رقــم ‪34175065‬وتاريخ‪1434/3/29‬ه ـ الصــادر مــن‬\n‫فضيلــة الشــيخ ‪......../‬القاضــي باحملكمــة العامــة بالطائــف املتضمــن‬\n‫دعوى‪......../‬مصــري اجلنســية وكالــة ضــد ‪......../‬ســعودي اجلنســية‬\n‫يف ديــة‪ ،‬احملكــوم فيــه مبــا دون بباطنــه ‪ ،‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والئحتــه االعتراضيــة قررنــا املوافقــة علــى احلكــم‪ ،‬واهلل املوفــق‬\n                  ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                                                          ‫‪244‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":239,"source_page_end":244,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5f8925fdba4dce4e8e205b1f9e0296f3c0dadf6164c881066b6930f0425a02d5","normalized_text_hash":"184ca621613a039520715c561e0060d6ccd31220dd0cf4c2fde2d6cc734cb417","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p239-34175065"},{"id":"a7ee0a34-7d42-54fc-a267-a50142cede19","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -دية قتل خطأ -وفاة مورث املدعيني نتيجة حادث سيارة وهروب السائق -مطالبة الورثة بيت املال بدفع دية مورثهم كاملة -أخذ المحكمة بأوراق املعاملة وتقرير املرور -عدم حضور املدعى عليه (ممثل بيت املال) رغم التبليغ يف الدعوى -احلكم حضوري بتسليم بيت املال الدية للمدعين.","document_number":"33209576","case_number":"32585816","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/25","year":"1434","subject":"دية -دية قتل خطأ -وفاة مورث املدعيني نتيجة حادث سيارة وهروب السائق -مطالبة الورثة بيت املال بدفع دية مورثهم كاملة -أخذ المحكمة بأوراق املعاملة وتقرير املرور -عدم حضور املدعى عليه (ممثل بيت املال) رغم التبليغ يف الدعوى -احلكم حضوري بتسليم بيت املال الدية للمدعين.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/4/25 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33209576 :‬‬\n                          ‫َر ْق ُم الدعوى‪32585816 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                      ‫‪ 345329‬تاريخه‪1434/1/7 :‬ه‬\n\n\n      ‫ديــة ‪ -‬ديــة قتــل خطــأ‪ -‬وفــاة مــورث املدعيني نتيجة حادث ســيارة وهروب‬\n      ‫الســائق‪ -‬مطالبــة الورثــة بيــت املــال بدفــع ديــة مورثهــم كاملــة‪ -‬أخــذ‬\n      ‫احملكمــة بــأوراق املعاملــة وتقريــر املــرور‪ -‬عــدم حضــور املدعــى عليــه‬\n      ‫(ممثــل بيــت املــال) رغــم التبليــغ يف الدعــوى‪ -‬احلكــم حضــوري بتســليم‬\n                                                    ‫بيــت املــال الديــة للمدعيــن‪.‬‬\n\n\n\n\n      ‫‪ .1‬جــاء يف كشــاف القنــاع ‪( 2981/8‬ويفــدى ميــت يف زحمــة كجمعــة‬\n                               ‫وطــواف روي عــن عمــر وعلــي واحتــج بــه أحمــد)‪.‬‬\n                   ‫‪ .2‬وجاء يف اإلنصاف ‪( 149/10‬هذا الصحيح من املذهب)‬\n      ‫‪ .3‬ويف املغنــي ‪( 48/12‬وروي أن رجــا قتــل يف زحــام يف زمــن عمــر فلــم‬\n      ‫يعطــل دم امــرئ‬\n                     ‫يعــرف قاتلــه فقــال علــي لعمــر يــا أميــر املؤمنــن ال ّ‬\n      ‫مســلم فــأدى ديتــه مــن بيــت املــال رواه عبــد الــرزاق وألن املســلمني يرثــون‬\n      ‫مــن ال وارث لــه فيعقلــون عنــه عنــد عــدم عاقلــة كعصباتــه ومواليــه)‬\n                                                                                       ‫أ‪.‬هـ‬\n      ‫‪ .4‬روى ابــن أبــي شــيبة عــن عــدي بــن أرطــاة أنــه كتــب إلــى عمــر بــن‬\n      ‫عبــد العزيــز أننــي وجــدت قتيــا يف احلــرم ال يعلــم مــن قتلــه فكتــب إليــه‬\n                                               ‫عمــر أن يــؤدى ديتــه مــن بيــت املــال ‪.‬‬\n                                        ‫‪ .5‬املادة ‪ 134‬من نظام املرافعات الشرعية‪.‬‬\n      ‫‪ .6‬تعميم رئيس املجلس األعلى للقضاء رقم ‪/192‬ت يف ‪1432/10/9‬هـ‬\n‫‪245‬‬\n\f‫بأن األمر امللكي رقم ‪ 43108‬يف ‪1432/10/2‬هـ اعتمد ما قررته احملكمة‬\n                    ‫العليــا بــأن ديــة قتــل اخلطــأ ثالثمائــة ألف ريال ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة ضــد منــدوب بيــت املــال الغائــب عــن مجلــس‬\n‫احلكــم بــأن مــورث موكلــه تــويف إثــر حــادث مــن قبــل ســيارة مــن نــوع‬\n‫بــاص ال يعــرف أوصافــه وقــد الذ ســائقها بالفــرار مــن موقــع احلــادث وقــد‬\n‫أدان تقريــر املــرور الســائق الهــارب بخمســن باملائــة مــن نســبة اخلطــأ‬\n‫ولــم يســتدل عليــه حتــى اآلن وقــد صــدر األمــر الســامي الكــرمي رقــم‬\n‫‪/52121‬م يف ‪1432/11/8‬ه ـ بســماع الدعــوى أمــام بيــت املــال ويطلــب‬\n‫احلكــم علــى منــدوب بيــت املــال بتســليم ديــة مورث موكله حســب نســبة‬\n‫اإلدانــة املشــار إليهــا‪ ،‬تبلــغ منــدوب بيــت املــال ولــم يحضــر فجــرى ســماع‬\n‫الدعــوى غيابي ـ ًا ‪ -‬جــرى االطــاع علــى تقريــر املــرور وذكــرت أســباب‬\n‫اإلدانــة بعبــور املتوفــى الطريــق دون التأكــد مــن خلــوه مــن الســيارات‬\n‫وعــدم أخــذ احليطــة واحلــذر مــن ســائق الســيارة املتســبب ‪ ،‬طلــب املدعــي‬\n‫الديــة كاملــة يف اجللســة التــي تليهــا ‪ ،‬مبــا أن املذكــور تــويف مــن جــراء‬\n‫صــدم ســيارة ال يعلــم قائدهــا ونظــر ًا لكــون املدعــى عليهــا تبلغــت ولــم‬\n‫حتضــر وممــا تقــرر شــرعا أن مــن قتــل ولــم يعلــم قاتلــه فــإن ديتــه راجعــة‬\n‫علــى بيــت املــال ( ينظــر كشــاف القنــاع ‪ 2981/8‬واالنصــاف ‪149/10‬‬\n‫واملغنــي ‪ ، ) 48/12‬وأمــا مــا ذكــره املــرور مــن تضمــن املســؤولية فهــو‬\n‫تقريــر غيــر وجيــه ألنهــم لــم يعاينــوا احلــادث وقــت وقوعــه بخصــوص عدم‬\n‫تأكــد املتوفــى مــن خلــو الطريــق فرمبــا أنــه تأكــد لكــن ســائق احلافلــة‬\n‫تهــور ولــم يحتــط فصدمــه وهــذا كثيــر يف احلــوادث املروريــة‪ ،‬ثــم تقريــر‬\n\n                                                                                      ‫‪246‬‬\n\f      ‫املــرور مــن جنــس رأي اخلبيــر تســتأنس بــه احملكمــة وال يقيدهــا كمــا‬\n      ‫أفــادت بــه املــادة ‪ 134‬مــن نظــام املرافعــات الشــرعية وبعــد االطــاع علــى‬\n      ‫تعميــم رئيــس املجلــس األعلــى للقضــاء رقــم ‪/192‬ت يف ‪1432/10/9‬ه ـ‬\n      ‫بــأن األمــر امللكــي رقــم ‪ 43108‬يف ‪1432/10/2‬ه ـ اعتمــد مــا قررتــه‬\n      ‫احملكمــة العليــا باعتبــار ديــة قتــل اخلطــأ ثالثمائــة ألــف ريــال ‪ ،‬ملــا تقــدم‬\n      ‫صــدر احلكــم علــى املدعــى عليــه بيــت املــال أن يســلم املدعيــن ديــة‬\n      ‫مورثهمــا ديــة قتــل اخلطــأ ثالثمائــة ألــف ريــال ‪ ،‬ويعتبــر هــذا احلكــم‬\n      ‫حضوريــا لتبلــغ املدعــى عليهــا بهــذه الدعــوى ‪ ،‬صــدق احلكــم بعــد‬\n                    ‫مداولــة مــن محكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة‬\n      ‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 32585816‬وتاريــخ‬\n      ‫‪ 1432/12/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321575550‬وتاريــخ‬\n      ‫‪ 1432/12/17‬ه ـ واملرفــق بهــا االمــر امللكــي رقــم ‪ 52121‬يف‬\n      ‫‪1432/11/8‬ه بــاإلذن يف ســماع هــذه الدعــوى حضــر ‪ ........‬مصــري‬\n      ‫ا عــن ‪ ........‬بصفتــه‬ ‫اجلنســية مبوجــب جــواز الســفر رقــم ‪ ........‬وكي ـ ً‬\n      ‫ا عــن ‪ ........‬و ‪ ........‬ورثــة ‪ ........‬مبوجــب الوكالــة الصــادرة مــن‬\n                                                                                ‫وكيـ ً‬\n      ‫مأموريــة الســيدة زينــب برقــم ‪210‬م يف ‪2011‬م مصدقــة مــن اخلارجيــة‬\n      ‫برقم ‪ 17‬يف ‪1432/6/4‬هـ و مصدقة من فرع وزارة العدل محافظة جدة‬\n      ‫برقــم ‪ 4379‬يف ‪1432/6/4‬ه ـ واملذكــورون هــم ‪ ........ ........‬مبوجــب‬\n      ‫حصــر الورثــة الصــادر مــن محكمــة الدخيلــة مبحافظــة االســكندرية‬\n      ‫بجمهوريــة مصــر العربيــة برقــم ‪ 2011/1426‬بتاريــخ ‪2011/9/14‬م‬\n‫‪247‬‬\n\f‫واملصــدق مــن اجلهــات املذكــورة ســابقا وانتظــر املدعــى عليــه منــدوب‬\n‫بيــت املــال ولــم يحضــر وقــد جــرى تبليغهــم باملوعــد الســابق واعتــذروا‬\n‫عــن احلضــور مبوجــب خطابهــم رقــم ‪ 588/201‬يف ‪1433/2182‬ه ـ‬\n‫ا‬‫واجــل املوعــد الــى هــذه اجللســة لطلبهــم ذلــك وأدعــى االول قائ ـ ً‬\n‫ان مــورث موكلــي ‪ ........‬توفــى بتاريــخ ‪1428/12/7‬ه ـ يف منطقــة‬\n‫‪ ........‬أثــر حــادث مــن قبــل ســيارة مــن نــوع بــاص ال يعــرف أوصافــه وقــد‬\n‫الذ ســائقها بالفــرار مــن موقــع احلــادث وقــد أدان تقريــر املــرور الســائق‬\n‫الهــارب بخمســن باملائــة مــن نســبة اخلطــأ ولــم يســتدل عليــه حتــى اآلن‬\n‫وقــد صــدر األمــر الســامي الكــرمي رقــم ‪/52121‬م يف ‪1432/11/8‬ه ـ‬\n‫بســماع الدعــوى أمــام بيــت املــال أطلــب احلكــم علــى منــدوب بيــت املــال‬\n‫بتســليم ديــة مــورث موكلــي حســب نســبة اإلدانــة املشــار إليهــا كونــه‬\n‫ممثــل بيــت املــال هــذه دعــواي ثــم اطلعــت علــى اوراق املعاملــة فوجــدت‬\n‫فيهــا محضــر املعاينــة علــى صفحــة ‪ 1‬مــن ملــف التحقيــق املرفــق لفــه‬\n‫‪ 25‬وهــذا نصــه انــه يف حوالــي الســاعة ‪ 8‬مســاء بتاريــخ ‪1428/12/7‬ه ـ‬\n‫تبلغــت انــا املــازم اول ‪ ........‬ضابــط خفــر حــوادث الشــرق عــن طريــق‬\n‫منــدوب احلــوادث املتواجــد يف مستشــفى النــور التخصصــي عــن‬\n‫مصــاب اثــر حــادث مــروري وحالتــه خطيــره وباالنتقــال الــى موقــع‬\n‫احلــادث ملعاينتــه وتخطيطــه واملوقــع يف العزيزيــة باجتــاه كبــري امللــك‬\n‫خالــد كمــا جــرى االنتقــال الــى مستشــفى النــور التخصصــي وذلــك‬\n‫لالطمئنــان علــى املصــاب ومعاينــة حالتــه وباالنتقــال الــى موقــع احلــادث‬\n‫ومعاينتــه اتضــح لنــا بانــه يقــع يف منطقــة العزيزيــة باجتــاه كبــري امللــك‬\n‫خالــد الطريــق الرئيســي حتديــدا امــام محــات ‪ ......‬علمــا أن الســيارة‬\n‫املتســببة ال توجــد يف املوقــع ولــم جنــد اي اثــار لهــا ولــم جنــد كذلــك‬\n\n\n                                                                                     ‫‪248‬‬\n\f      ‫شــهود عيــان ســوى مــا أفــاد بــه مســعفو الهــال األحمــر ملندوبنــا حســب‬\n      ‫افــادة مــن شــاهد احلــادث ان املصــاب مضغــوط بــن باصــن وال يعــرف اي‬\n      ‫مواصفــات للبــاص املتســبب كذلــك لــم جنــد اي اثــار دمــاء للمدهــوس‬\n      ‫او اثــار لــه يف املوقــع علمــا ان الطريــق ثــاث مســارات والرؤيــة واضحــه‬\n      ‫ومكشــوفه ووقــت احلــادث ايــام موســم احلــج ويوجــد باملوقــع حركــة‬\n      ‫مشــاه وســيارات ووقــت ذروه ومــن خــال انتقالنــا للموقــع وبحثنــا عــن‬\n      ‫شــهود عيــان لــم جنــد مــن شــاهد احلــادث ســوى ان مســعفي الهــال‬\n      ‫االحمــر افــادوا املنــدوب املتواجــد مبستشــفى ‪ ........‬املصــاب قــد أصيــب‬\n      ‫بســبب تواجــده بــن باصــن أثــرا عليــه قامــا بالضغــط عليــه ممــا أدى‬\n      ‫الــى اصابتــه وحصــول احلــادث علمــا بــان الســيارة املتســببة هــي مــن نــوع‬\n      ‫بــاص وال يوجــد أي معلومــات عنهــا حيــث الذ الســائق بالهــرب مــن نفــس‬\n      ‫املوقــع وتعــزى اســباب املؤديــة لوقــوع احلــادث الــى قيــام املدهــوس بعبــور‬\n      ‫الطريــق دون التأكــد مــن خلــوه مــن الســيارات كذلــك عــدم اخــذ‬\n      ‫احليطــة واحلــذر مــن الســائق املتســبب وجنــم عــن احلــادث اصابــة الشــخص‬\n      ‫املدهــوس ومت نقلــه بواســطة الهــال االحمــر الــى مستشــفى النــور علمــا‬\n      ‫بــان الســائق املتســبب قــد الذ بالفــرار وال يوجــد أي معلومــات عنــه وأن‬\n      ‫الســيارة مــن نــوع بــاص وكان الوقــت الســاعة ‪ 8‬مســاء واجلــو صحــو‬\n      ‫والطريــق مســتقيم ومكشــوف والرؤيــة واضحــه وال يوجــد مــا يعيقهــا‬\n      ‫ا‪.‬ه ـ ثــم اطلعــت علــى شــهادة الوفــاة الصــادرة مــن االحــوال املدنيــة مبكــة‬\n      ‫املكرمــة ملــورث املدعــن وهــي برقــم ‪ ........‬يف ‪1428/12/26‬ه ـ وســبب‬\n      ‫احلــادث مــروري وان ديانــة املتوفــى االســام لــذا ســوف يطلــب وكيــل‬\n      ‫بيــت املــال يف اجللســة القادمــة وافهامــه بانــه اذا لــم يحضــر فســوف‬\n      ‫يحكــم عليــه ويف جلســة أخــرى حضــر املدعــي وكالــة وانتظــر وكيــل‬\n\n\n‫‪249‬‬\n\f‫وزارة املاليــة ولــم يحضــر وقــرر املدعــي أنــه ال يكتفــي مبــا قــرره املــرور‬\n‫ويطلــب احلكــم بديــة مــورث املدعــن كاملــه وبعــد النظــر يف الدعــوى‬\n‫واإلجابــة وتأسيســا علــى مــا جــرى رصــده مــن إثباتــات احلادث ومــا يتبعها‬\n‫مــن شــهادة الوفــاة مــن جــراء احلــادث املــروري والتقريــر مــن إدارة املــرور‬\n‫وغيــر ذلــك واملثبتــة أن املذكــور تــويف مــن جــراء صــدم ســيارة ال يعلــم‬\n‫قائدهــا ونظــرا لكــون املدعــى عليهــا تبلغــت ولــم حتضــر وممــا تقــرر‬\n‫شــرعا أن مــن قتــل ولــم يعلــم قاتلــه فــإن ديتــه راجعــة علــى بيــت املــال قــال‬\n‫يف كشــاف القنــاع ‪ 2981/8‬ويفــدى ميــت يف زحمــة كجمعــه وطــواف‬\n‫روي عــن عمــر وعلــي واحتــج بــه أحمــد وقــال يف االنصــاف ‪149/10‬‬\n‫هــذا الصحيــح مــن املذهــب ويف املغنــي ‪ 48/12‬وروى أن رجــا قتــل يف‬\n‫زحــام يف زمــن عمــر فلــم يعــرف قاتلــه فقــال علــي لعمــر يــا أميــر املؤمنــن‬\n‫ال يطــل دم امــرئ مســلم فــأدى ديتــه مــن بيــت املــال ( رواه عبــد الــرزاق‬\n‫) وألن املســلمني يرثــون مــن ال وارث لــه فيعقلــون عنــه عنــد عــدم عاقلــة‬\n‫كعصباتــه ومواليــه أ‪.‬ه ـ وروي أبــن أبــي شــيبه عــن عــدي بــن أرطــاه‬\n‫أنــه كتــب إلــى عمــر بــن عبــد العزيــز أننــي وجــدت قتيــا يف احلــرم ال‬\n‫يعلــم مــن قتلــه فكتــب إليــه عمــر أن يــؤدى ديتــه مــن بيــت املــال وأمــا مــا‬\n‫ذكــره املــرور مــن تضمــن املســؤولية فهــو تقريــر غيــر وجيــه ألنهــم لــم‬\n‫يعاينــوا احلــادث وقــت وقوعــه فكيــف يقولــون لــم يتأكــد املتــويف مــن‬\n‫خلــو الطريــق فــر مبــا أنــه تأكــد لكــن ســائق احلافلــة تهــور ولــم يحتــط‬\n‫فصدمــه وهــذا كثيــر يف احلــوادث املروريــة ثــم تقريــر املــرور مــن جنــس‬\n‫رأي اخلبيــر تســتأنس بــه احملكمــة وال يقيدهــا كمــا أفــادت بــه املــادة‬\n‫‪ 134‬مــن نظــام املرافعــات الشــرعية وبعــد اطالعــي علــى تعميــم رئيــس‬\n‫احملكمــة األعلــى للقضــاء رقــم ‪/192‬ت يف ‪1432/10/9‬ه ـ بــأن األمــر‬\n\n\n                                                                                           ‫‪250‬‬\n\f      ‫امللكــي رقــم ‪ 43108‬يف ‪1432/10/2‬ه ـ اعتمــد مــا قررتــه احملكمــة‬\n      ‫العليــا باعتبارهــا ديــة قتــل اخلطــأ ثالثمائــة ألــف ريــال لذلــك فقــد‬\n      ‫حكمــت علــى املدعــى عليــه بيــت املــال أن يســلم املدعــن ديــة مورثهــم‬\n      ‫ديــة قتــل اخلطــأ ثالثمائــة ألــف ريــال وســوف يبلــغ املدعــى عليهــا بنســخه‬\n      ‫مــن احلكــم ويعتبــر هــذا احلكــم حضوريــا لتبلــغ املدعــى عليهــا بهــذه‬\n                               ‫الدعــوى وبــاهلل التوفيــق حــرر يف ‪1433/4/21‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فقــد‬\n      ‫عــادت املعاملــة مــن محكمــة االســتئناف باخلطــاب رقــم ‪331168705‬‬\n      ‫يف ‪1433/7/19‬ه ـ وبرفقــه القــرار رقــم ‪ 33326447‬يف ‪1433/7/5‬ه ـ‬\n      ‫املتضمــن وبدراســة الصــك و صــورة ضبطــه والالئحــة االعتراضيــة تقــرر‬\n      ‫باألكثريــة إعادتهــا لفضيلــة حاكمهــا ملالحظــة مــا يلــي ‪1:‬ـ إن دعــوى‬\n      ‫املدعــي بتســليم ديــة مــورث موكليهــم حســب النســبة املعــدة مــن قبــل‬\n      ‫املــرور خمســن يف املائــة وحكــم فضيلتــه بالديــة كاملــة وهــذا محــل‬\n      ‫نظــر ‪2‬ـ أن املبلــغ املطلــوب احلكــم بــه لصالــح املدعــي وكالــة غيــر معلوم‬\n      ‫يف الدعــوى والبــد مــن حتريــر ذلــك ‪3‬ـ يف الالئحــة االعتراضيــة املقدمــة‬\n      ‫مــن املدعــى عليــه مديــر مكتــب وزارة املاليــة فيــه أمــور تســتدعي‬\n      ‫التوقــف عندهــا ملالحظــة ذلــك ‪4‬ـ أنــه ورد أخطــاء إمالئيــة ‪5‬ـ تســبيب‬\n      ‫حكمــه مبــا ذكــره مــن أدلــة مخالــف لواقعــة الدعــوى واهلل املوفــق‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم أ‪.‬ه ـ وعليــه‬\n      ‫أجيــب أصحــاب الفضيلــة عفــا اهلل عنهــم أوال بــان املدعــي وكالــة قــد‬\n      ‫غيــر دعــواه وعدلهــا ورصــدت ذلــك بضبطــه وصكــه وهــو يف الســطر‬\n      ‫األول مــن الصفحــة الثانيــة مــن الصــك اطلــب احلكــم بالديــة كاملــة‬\n      ‫وال يخفــى أن نظــام املرافعــات جعــل للمدعــي قبــل قفــل بــاب املرافعــة أن‬\n\n\n‫‪251‬‬\n\f‫يعــدل يف دعــواه ويقــدم فيهــا و يؤخــر حســب املــادة التاســعة والســبعني‬\n‫منــه ثانيـ ًا مــا طلــب املدعــي وكالــة يف طلبــه األخيــر معلــوم مشــهور فــان‬\n‫الديــة ســابق ًا معلومــة لــدى النــاس عامــة أنهــا مائــة ألــف ريــال ثــم زيــدت‬\n‫إلــى ثالثمائــة ألــف ريــال واشــتهر ذلــك عنــد العمــوم وللمدعــي أن يهمــل‬\n‫مــن دعــواه مــا اشــتهر بــن النــاس و عــرف واســتغنى بشــهرته عــن تعينيــه‬\n‫وقــد بينتــه أيض ـ ًا حكم ـ ًا و قنــع بــه املدعــي وكالــة ثالث ـ ًا أمــا الالئحــة‬\n‫االعتراضيــة فلــم أجــد فيهــا مــا يســتحق النظــر و لــو وجدتــه لفتحــت‬\n‫بــاب املرافعــة رابعـ ًا أمــا األخطــاء اإلمالئيــة فلــم أجــد خطــأ إمالئيـ ًا فيمــا‬\n‫اطلعــت عليــه ومــا علــم عليــه بالرصــاص مــن كلمــة احملكمــة األعلــى‬\n‫للقضــاء فخطــا لفظــي ال إمالئــي جــرى اســتدراكها ومــا عــداه فلــم‬\n‫يظهــر لــي فيــه وجــه خطــأ خامس ـ ًا أمــا أن تســبيب حكمــي مخالف ـ ًا‬\n‫لواقعــة الدعــوى فذلــك غيــر صحيــح وان كان مخالف ـ ًا فاطلــب بيــان‬\n‫املخالفــة وأمــا منــدوب املاليــة فجــرى تبليغــه فلــم يحضــر لــذا ســرت‬\n‫بالقضيــة كمــا تقتضيــه التعليمــات املنصوصــة يف نظــام املرافعــات‬\n‫تنظــر املــادة اخلامســة و اخلمســن منــه لــذا فانــي تأملــت جيــدا وهــذا مــا‬\n‫أراه أبــرأ للذمــة وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فقــد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف باخلطــاب رقــم ‪331468616‬‬\n‫يف ‪1433/8/14‬هـ وبرفقه اإلقرار رقم ‪ 33375588‬يف ‪1433/8/12‬هـ‬\n‫املتضمــن وبدراســة الصــك و صــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n‫إعادتهــا لفضيلــة حاكمهــا ملالحظــة مــا يلــي ‪1‬ـ إجابتــه حاكــم القضيــة‬\n         ‫غيــر مقنعــة خصوصـ ًا فيمــا يخــص الفقــرة أو ًال وثانيـ ًا و خامسـ ًا ‪.‬‬\n‫‪2‬ـ حكــم فضيلتــه بثالثمائــة ألــف ريــال ديــة اخلطــأ كاملــة يف غيــر‬\n\n\n                                                                                            ‫‪252‬‬\n\f      ‫محلــه وعليــه الرجــوع عــن حكمــه واحلكــم بالنســبة املروريــة املقيــدة‪.‬‬\n      ‫‪3‬ـ لــم يقســم القاضــي الديــة حســب النســبة املروريــة علــى الورثــة حســب‬\n      ‫الفريضــة الشــرعية ‪4 .‬ـ الالئحــة االعتراضيــة فيهــا أمــور ملفتــه للنظــر‬\n      ‫ينبغــي إعــادة دراســتها مــن جديــد فعلــى فضيلته إعادة النظــر يف القضية‬\n      ‫والتأمــل والتمعــن واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آله و‬\n      ‫صبحــه وســلم أ‪.‬ه ـ عليــه أجيــب أصحــاب الفضيلــة وفقهــم اهلل عــز وجــل‬\n      ‫بأنــه مــا ذكــر يف قــرار املالحظــة ســبقت اإلجابــة عنــه ولــم أحكــم يف‬\n      ‫القضيــة إال وأنــا بــإذن اهلل محيــط بهــا وأمــا الالئحــة االعتراضيــة فــإن‬\n      ‫كان فيهــا مــا يوحــي بإشــكال علــى إجرائــي نأمــل بيانــه لإلجابــة عنــه‬\n           ‫واهلل أعلــم وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه و صبحــه وســلم‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى رســول اهلل ‪ ...‬وبعــد‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الســابعة يف محكمــة‬\n      ‫اإلســتئناف مبنطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪33/1538753‬‬\n      ‫وتاريــخ‪1433/12/ 20‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪ ........ /‬القاضــي باحملكمــة العامــة مبكــة املكرمــة برقــم‬\n      ‫‪ 33209576‬وتاريــخ ‪1433/4/25‬ه ـ احملكــوم فيــه مبــا دون بباطــن‬\n      ‫الصــك ‪ ،‬املتضمــن دعــوى ورثــة ‪ ........‬ضــد‪ ........‬بيــت املــال يف ديــة ‪،‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم بعــد‬\n      ‫اجلــواب االخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                    ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪253‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":245,"source_page_end":253,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a1909f1c967d23634815c38b93d103619e87efc1bbaf742599bb4727575aefb8","normalized_text_hash":"20d33a6d6b3165d4efa8a8b3ce1ebe617daeeb0aa93cd42e114609567ea0e1a3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p245-33209576"},{"id":"bbe2dbd5-8ab4-594c-a4ed-450b8acd78ce","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية متوفى -حادث مروري [تصادم بإبل سائبة] -سماع الدعوى ضد بيت املال لعدم معرفة صاحب اإلبل -وجوب تضمن املتسبب -اليبطل دم امرئ مسلم -احلكم على بيت املال بتسليم دية املتوفى -ضمان ماتتلفه بهيمة األنعام -إفهام وزارة املالية باحلق يف الرجوع بالدية على مالك الدابه املتسبب حال العثور عليه .","document_number":"33483021","case_number":"33191193","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/29","year":"1434","subject":"دية متوفى -حادث مروري [تصادم بإبل سائبة] -سماع الدعوى ضد بيت املال لعدم معرفة صاحب اإلبل -وجوب تضمن املتسبب -اليبطل دم امرئ مسلم -احلكم على بيت املال بتسليم دية املتوفى -ضمان ماتتلفه بهيمة األنعام -إفهام وزارة املالية باحلق يف الرجوع بالدية على مالك الدابه املتسبب حال العثور عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/12/29 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33483021 :‬‬\n                    ‫َر ْق ُم الدعوى‪33191193 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 3416009‬تاريخه‪1434/1/19:‬هـ‬\n\n\n ‫ديــة متوفــى ‪ -‬حــادث مــروري [تصــادم بإبــل ســائبة] ‪ -‬ســماع الدعــوى‬\n ‫ضــد بيــت املــال لعــدم معرفــة صاحــب اإلبــل ‪ -‬وجــوب تضمــن املتســبب‬\n ‫‪ -‬اليبطــل دم امــرئ مســلم ‪ -‬احلكــم علــى بيــت املــال بتســليم ديــة‬\n ‫املتوفــى ‪ -‬ضمــان ماتتلفــه بهيمــة األنعــام ‪ -‬إفهــام وزارة املاليــة باحلــق‬\n ‫يف الرجــوع بالديــة علــى مالــك الدابــه املتســبب حــال العثــور عليــه ‪.‬‬\n\n\n\n\n ‫‪ .1‬عمــوم حديــث عبــادة بــن الصامــت أن رســول اهلل صلــى اهلل عليــه‬\n                                      ‫وســلم قــال ‪ ( :‬ال ضــرر وال ضــرار ) ‪.‬‬\n ‫‪ .2‬حديــث حــرام بــن ســعد أن ناقــة للبــراء بــن عــازب دخلــت حائــط رجــل‬\n ‫فأفســدت فيــه فقضــى رســول اهلل صلــى اهلل عليــه وســلم أن علــى أهــل‬\n ‫احلوائــط حفظهــا بالنهــار وأن مــا أفســدت املواشــي ضامــن علــى أهلهــا‪.‬‬\n ‫رواه أحمــد وغيــره ومعنــى ضامــن ( مضمــون ) وهــو مخصــص لقولــه‬\n ‫صلــى اهلل عليــه وســلم ( العجمــاء جرحهــا جبــار ) املتفــق عليــه مــن‬\n                                        ‫حديــث أبــي هريــرة رضــي اهلل عنــه ‪.‬‬\n ‫‪ .3‬القواعــد الفقهيــة‪ -1 :‬األصــل أن املشــي يف طريــق املســلمني مبــاح‬\n ‫بشــرط الســامة فيمــا ميكــن التحــرز منــه ‪ -2 .‬املتســبب ضامــن إن‬\n                                                               ‫فــرط أو تعــدى ‪.‬‬\n ‫‪ .4‬مــا قــرره أهــل العلــم املعاصــرون مــن أن حــوادث الســيارات كلهــا‬\n ‫تلحــق باخلطــأ ‪ ،‬ليــس فيهــا قصــاص ‪ ،‬ولكــن فيهــا الديــة ( شــرح أخصــر‬\n                                                                                    ‫‪254‬‬\n\f                                            ‫املختصــرات يف الفقــه البــن جبريــن ) ‪.‬‬\n      ‫‪ « .5‬وملــا كان الصحيــح يف مســألة تضمــن مالــك احليــوان إن لــم‬\n      ‫ا فعليــه الضمــان وإن‬    ‫يكــن حتــت يــده وفــرط التفصيــل فــإن وقــع لي ـ ً‬\n      ‫وقــع نهــار ًا فــا ضمــان وهــو قــول املالكيــة ( بدايــة املجتهــد ‪) 242/2‬‬\n      ‫ومغنــي احملتــاج ( ‪ ، ) 204/4‬واإلنصــاف ( ‪ ) 241/6‬واختيــار جمــع مــن‬\n      ‫احملققــن كابــن القيــم ( إعــام املوقعــن ‪ ) 326/1‬الشــوكاني ( نيــل‬\n                                                                   ‫األوطــار ‪. ) 325/5‬‬\n      ‫‪ .6‬قــال يف الــروض املربــع ( مــا أتلفــت البهيمــة مــن الــزرع والشــجر‬\n      ‫ال ضمنه صاحبها وعكســه النهار ) ( الروض مع احلاشــية‬               ‫وغيرهما لي ً‬\n                                                                             ‫‪. ) 418/5‬‬\n      ‫‪ .7‬وألنــه ال يبطــل دم مســلم ملــا يف حديــث القســامة ويف آخــره ( فكــره‬\n      ‫رســول اهلل صلــى اهلل عليــه وســلم أن يبطــل دمــه ‪ ،‬فــواده مائــة مــن إبــل‬\n                                                                            ‫الصدقــة )‬\n\n\n\n\n      ‫ادعــى املدعــي أن ابنــه قــد تــويف يف حــادث اصطــدام بإبــل ســائبة وأديــن‬\n      ‫مالــك اجلمــل بكامــل املســؤولية ‪ ،‬وقــد بحــث عــن مالــك اجلمــل فلــم‬\n      ‫يعثــر عليــه ‪ ،‬وطلــب احلكــم علــى وزارة املاليــة بتســليم ديــة مورثــه‪،‬‬\n      ‫حضــر منــدوب وزارة املاليــة وأحضــر جواب ـ ًا محــرر ًا تضمــن أن الفقهــاء‬\n      ‫ذكــروا بــأن مــا أتلفتــه البهيمــة ســواء كان آدمي ـ ًا أو مــا ًال فــا ضمــان‬\n      ‫علــى صاحبهــا إذا لــم تكــن يــده عليهــا ‪ ،‬فبيــت املــال أولــى وطلــب‬\n      ‫صــرف النظــر عــن دعــوى املدعــي ‪ ،‬صــدر اإلذن مــن املقــام الســامي‬\n      ‫بســماع الدعــوى ضــد بيــت املــال ‪ ،‬مت االطــاع علــى صــك حصــر الورثــة‪،‬‬\n\n‫‪255‬‬\n\f‫كمــا جــرى االطــاع علــى الــوكاالت وصــك الواليــة ‪ ،‬جــرى االطــاع‬\n‫علــى تقريــر احلــادث املــروري املتضمــن إدانــة صاحــب الناقــة ملســؤولية‬\n‫احلــادث بنســبة ‪ % 100‬ومــا زال البحــث عنــه ‪ ،‬علم ـ ًا بــأن الوســم يعــود‬\n‫ألحــد القبائــل ـ األدلــة الشــرعية دلــت علــى تضمــن املفــرط‪ ،‬حديــث‬\n‫النبــي صلــى اهلل عليــه وســلم ( أن علــى أهــل احلوائــط ‪ ) ..‬مخصــص‬\n‫لقولــه صلــى اهلل عليــه وســلم ( العجمــاء جرحهــا جبــار )‪ ،‬احلكــم علــى‬\n‫وزارة املاليــة بتســليم ديــة املتوفــى‪ ،‬إفهــام الــوزارة بــأن لهــا حــق الرجــوع‬\n‫علــى مالــك الدابــة املتســبب يف حالــة العثــور عليــه‪ ،‬إفهــام املدعــي‬\n‫بــأن الديــة تقســم علــى الورثــة حســب امليــراث الشــرعي‪ ،‬قــرر املدعــي‬\n‫القناعــة واملدعــى عليــه قــرر عــدم القناعــة بــدون الئحــة اعتراضيــة‪،‬‬\n‫صــدق احلكــم مــن محكمــة االســتئناف‪ ،‬مت تســليم الشــيك للمدعــي‬\n                                 ‫أصالــة ووكالــة واعتبــار القضيــة منتهيــة ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنا‪.........‬القاضــي يف احملكمــة العامــة‬\n‫باملدينة املنورة وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة‬\n‫العامــة باملدينــة املنــورة برقــم ‪ 33191193‬وتاريــخ ‪ 1433/03/16‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 33506116‬وتاريــخ ‪ 1433/03/16‬ه ـ يف‬\n‫يــوم الثالثــاء املوافــق‪ 1433/07/15‬ه ـ فتحــت اجللســة الســاعة ‪10 : 00‬‬\n‫وفيهــا حضــر ‪ .........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.........‬‬\n‫باألصالــة عــن نفســه وبوكالتــه عــن ‪ .........‬بالوكالــة رقــم ‪35288‬‬\n‫وتاريــخ ‪1433/5/19‬ه ـ الصــادرة مــن كتابــة عــدل املدينــة املنــورة‬\n‫وعــن باألصالــة عــن نفســها وبواليتهــا علــى ابنتيهــا ‪ ...‬و‪ ...‬بالوكالــة‬\n\n                                                                                        ‫‪256‬‬\n\f      ‫رقــم ‪ 3386236‬وتاريــخ ‪1433/5/24‬ه ـ الصــادرة مــن كتابــة عــدل‬\n      ‫مكــة املكرمــة وحضــر حلضــوره محامــي وزارة املاليــة ‪ .........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم‪ .........‬املكلــف مبوجــب خطــاب‬\n      ‫مديــر عــام فــرع وزارة املاليــة مبنطقــة املدينــة املنــورة رقــم ‪ 55746‬وتاريــخ‬\n      ‫ا ‪ :‬إن ولــدي ‪ ...‬تــويف يف حــادث‬         ‫‪1433/7/12‬ه ـ وادعــى املدعــي قائ ـ ً‬\n      ‫اصطــدام بإبــل ســائبة علــى طريــق تيمــاء تبــوك بتاريــخ ‪1429/6/21‬ه ـ‬\n      ‫وأديــن مالــك اجلمــل بكامــل مســؤولية احلــادث وبالبحــث عنــه لــم يعثــر‬\n      ‫عليــه وقــد صــدر األمــر الســامي رقــم ‪ 9996‬وتاريــخ ‪1432/1/26‬ه ـ‬\n      ‫باملوافقــة علــى ســماع دعــواي باملطالبــة بالديــة يف مواجهــة منــدوب عــن‬\n      ‫بيــت املــال‪ ،‬أطلــب احلكــم علــى وزارة املاليــة بتســليم ديــة مورثــي ومــورث‬\n      ‫موكلــي هــذه دعــواي وطلــب منــه إبــراز صــك حصــر الورثــة والواليــة‬\n      ‫فأبــرز الصــك رقــم ‪ 22/100/542‬وتاريــخ ‪1429/8/15‬ه ـ الصــادر مــن‬\n      ‫احملكمــة العامــة مبحافظــة جــدة وباالطــاع عليــه وجــد يتضمــن ثبــوت‬\n      ‫وفــاة بتاريــخ ‪1429/6/22‬ه ـ وانحصــار ورثتــه يف والــده ‪ ...‬ووالدتــه‪.........‬‬\n      ‫وزوجتــه‪ .........‬وابنتيــه القاصرتــن‪ .........‬و ‪ .........‬وجــرى االطــاع علــى‬\n      ‫الصــك رقــم ‪ 33249471‬وتاريــخ ‪1433/5/16‬ه ـ الصــادر مــن احملكمة‬\n      ‫العامــة مبحافظــة جــدة ووجــد يضمــن إقامــة ولي ـ ًا علــى ابنتيهــا بنتــي‪.‬‬\n      ‫ا ‪ :‬أطلــب نســخة مــن الدعــوى‬       ‫وبعــرض ذلــك علــى املدعــى عليــه قــرر قائـ ً‬\n      ‫لإلجابــة عليهــا يف اجللســة القادمــة فأجيــب لطلبــه ورفعــت اجللســة إلــى‬\n      ‫يــوم الســبت املوافــق ‪1433/10/21‬ه ـ الســاعة العاشــرة صباحـ ًا وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                               ‫حــرر يف ‪ 1433/07/15‬ه ـ‬\n      ‫ويف يــوم الســبت املوافــق ‪1433/10/21‬ه ـ فتحــت اجللســة الســاعة‬\n\n\n‫‪257‬‬\n\f‫العاشــرة صباحـ ًا وفيهــا حضــر املدعــي وكالــة وحضــر حلضــوره محامــي‬\n‫وزارة املاليــة وبســؤال املدعــى عليــه وكالــة عــن جوابه عــن دعوى املدعي‬\n‫أجــاب ‪ :‬ال مانــع لدينــا مــن احلكــم علينــا بديــة املتوفــى إن ثبــت لــدى‬\n‫فضيلتكــم عــدم االســتدالل علــى مالــك املتســبب يف احلــادث مــع حفــظ‬\n‫حــق الــوزارة يف الرجــوع علــى املالــك يف حالــة االســتدالل عليــه هكــذا‬\n‫أجــاب وللتأمــل رفعــت اجللســة ليــوم الســبت ‪1433/10/28‬ه ـ الســاعة‬\n‫احلاديــة عشــرة والنصــف صباحـاً‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                               ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/10/21‬ه ـ‬\n‫ثــم حضــر منــدوب املاليــة املدعــى عليــه وقــرر قائـاً‪ :‬لقــد كان جوابنــا‬\n                                                    ‫الســابق خطــأ إذ حصــل خلـ ٌ‬\n‫ـط بــن كــون اجلانــي إنســان ًا أو داب ـ ًة وأريــد‬\n‫ـواء كان آدمي ـ ًا أو مــا ًال‬\n                             ‫أن أصحــح اجلــواب بــأن‪( :‬مــا أتلفتــه البهيمــة سـ ٌ‬\n‫فــا ضمــان علــى صاحبهــا إذا لــم تكــن يــده عليهــا كمــا ســئل ســماحة‬\n‫الشــيخ‪- ........./‬يرحمــه اهلل‪ -‬إذا كان اجلمــل أكــو ًال وصاحبــه مهملــه‬\n‫فأجــاب‪ :‬الظاهــر ال يضمــن الفتــاوى ج‪ 8‬ص‪ -168‬انتهــى كالمــه‬\n‫يرحمــه اهلل فــإذا كان هــذا يف حــق املالــك فبيــت املــال مــن بــاب‬\n‫أولــى‪ .‬لــذا أطلــب صــرف النظــر عــن دعــوى املدعــي ضــد بيــت املــال‪).‬‬\n‫هكــذا أجــاب‪ .‬وبعــرض جوابــه علــى املدعــي أجــاب‪ :‬ال أقتنــع بجــواب‬\n‫املدعــى عليــه وكالــة فــإن الســرعة كانــت معقولــة والدابــة كانــت‬\n‫مهملــة وباالطــاع علــى أوراق املعاملــة وجــدت تقريــر احلــادث املــروري‬\n‫ونــص احلاجــة منــه‪( :‬لقــد جــرى البحــث والتحــري عــن صاحــب الناقــة‬\n‫واتضــح لنــا بأنهــا تعــود لفخــذ ‪ ...‬مــن ‪ ...‬حســب الوســم املوجــود عليهــا‬\n‫والزال البحــث جاري ـ ًا عــن صاحبهــا‪ .‬املســؤولية‪ -:‬أوالً‪ :‬ظهــر لنــا مــن‬\n‫معاينــة احلــادث واآلثــار املتخلفــة بعــد احلــادث والرســم الكروكــي إدانــة‬\n\n\n                                                                                       ‫‪258‬‬\n\f      ‫صاحــب الناقــة مبســؤولية احلــادث بواقــع ‪ %100‬وذلــك لألســباب التاليــة‪:‬‬\n      ‫‪ -1‬اهمالــه إلبلــه وعــدم احملافظــة عليهــا‪ -2 .‬كــون احلــادث وقــع لي ـاً‪.‬‬\n      ‫ثاني ـاً‪ :‬ويعفــى قائــد الســيارة ‪ ...‬املذكــور مــن مســئولية احلــادث وذلــك‬\n      ‫لألســباب التاليــة‪ -1 :‬كونــه يســير بخــط ســيره الصحيــح ‪ -2‬اعتــراض‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى‬    ‫اإلبــل فجــأة بخــط ســيره لي ـاً‪ ).‬فبنـ ً‬\n      ‫واإلجابــة ولألدلــة الدالــة علــى تضمــن املفــرط ومنهــا‪ :‬أوالً‪ :‬مــا حــكاه‬\n      ‫اهلل تعالــى يف كتابــه الكــرمي يف قصــة داوود وســليمان عليهمــا الســام‬\n      ‫مــع صاحــب الغنــم التــي نفشــت يف احلــرث فقــد اجتمــع رأيهمــا علــى‬\n      ‫تضمــن املتســبب وإن اختلفــا يف طريقــة التضمــن‪ .‬ثانيـاً‪ :‬عمــوم حديــث‬\n      ‫عبــادة بــن الصامــت أن رســول اهلل صلــى اهلل عليــه وســلم قــال‪( :‬ال ضــرر‬\n      ‫وال ضــرار) ثالثـاً‪ :‬حديــث حــرام بــن ســعد أن ناقــة للبراء بــن عازب دخلت‬\n      ‫حائــط رجــل فأفســدت فيــه فقضــى رســول اهلل صلــى اهلل عليــه وســلم‬\n      ‫أن علــى أهــل احلوائــط حفظهــا بالنهــار وأن مــا أفســدت املواشــي ضامــن‬\n      ‫علــى أهلهــا رواه أحمـ ٌـد وغيــره ومعنــى ضامــن (مضمــون) وهــو مخصــص‬\n      ‫لقولــه صلــى اهلل عليــه وســلم (العجمــاء جرحهــا جبــار) املتفــق عليــه مــن‬\n      ‫حديــث أبــي هريــرة رضــي اهلل عنــه‪ .‬رابعـاً‪ :‬كثيــر مــن القواعــد الفقهيــة‬\n      ‫ومنهــا‪ -1 :‬األصــل أن املشــي يف طريــق املســلمني مبــاح بشــرط الســامة‬\n      ‫فيمــا ميكــن التحــرز منــه‪-2 .‬املتســبب ضامــن إن فــرط أو تعدى‪.‬وغيرهــا‬\n      ‫وملــا قــرره أهــل العلــم املعاصــرون مــن أن حــوادث الســيارات كلهــا تلحــق‬\n      ‫ـاص ولكــن فيهــا الديــة (شــرح أفقــه املختصــرات‬     ‫باخلطــأ ليــس فيهــا قصـ ٌ‬\n      ‫البــن جبريــن) وملــا كان الصحيــح يف مســألة تضمــن مالــك احليــوان إن‬\n      ‫ا فعليــه الضمــان‬   ‫لــم يكــن حتــت يــده وفــرط التفصيــل فــإن وقــع لي ـ ً‬\n      ‫وإن وقــع نهــار ًا فــا ضمــان عليــه وهــو قــول املالكيــة (بدايــة املجتهــد‬\n\n\n‫‪259‬‬\n\f‫‪ )242/2‬ومغنــي احملتــاج (‪ )204/4‬واإلنصــاف (‪)241/6‬واختيــار جمــع‬\n‫مــن احملققــن كابــن القيــم (إعــام املوقعــن ‪ )326/1‬والشــوكاني‬\n‫(نيــل األوطــار ‪ )325/5‬قــال يف الــروض املربــع (ومــا أتلفــت البهيمــة‬\n‫ا ضمنــه صاحبهــا وعكســه النهــار)‬           ‫مــن الــزرع والشــجر وغيرهمــا لي ـ ً‬\n‫(الــروض مــع احلاشــية ‪ )418/5‬ولعــدم العثــور علــى مالــك الدابــة وألنــه‬\n‫ال يبطــل دم مســلم ملــا يف حديــث القســامة ويف آخــره (فكــره رســول‬\n‫اهلل صلــى اهلل عليــه وســلم أن يبطــل دمــه فــوداه مائـ ًة مــن إبــل الصدقــة‬\n‫وملــا جــاء يف تقريــر املــرور الســابق فقــد قــررت مــا يلــي‪ :‬أوالً‪ :‬احلكــم‬\n‫علــى وزارة املاليــة بتســليم ديــة املتوفــى وقدرهــا ثالثمائــة ألــف ديــة املســلم‬\n‫الذكــر احلــر املقتــول خطــأ‪ .‬ثانيـاً‪ :‬للــوزارة احلــق يف الرجــوع بالديــة علــى‬\n‫مالــك الدابــة املتســبب يف حالــة العثــور عليــه‪ .‬ثالث ـاً‪ :‬إفهــام املدعــي بــأن‬\n‫الديــة تركــة تقســم علــى الورثــة حســب امليــراث الشــرعي‪ .‬هــذا مــا‬\n‫ظهــر لــي وبــه حكمــت وبعرضــه علــى الطرفــن قــرر املدعــي القناعــة‬\n‫وقــرر املدعــى عليــه عــدم القناعــة وطلــب رفعــه حملكمــة االســتئناف‬\n‫دون الئحــة اعتراضيــة لــذا أمــرت برفعــه لالســتئناف لتدقيقــه كاملتبــع‬\n‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                       ‫‪ .‬حــرر يف ‪1433/11/14‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ :‬ثــم عــادت املعاملــة مــن حكمــة االســتئناف‬\n‫مبكــة بخطابهــا رقــم ‪ 3489887‬يف ‪1434/01/26‬ه ـ مرفــق بــه‬\n‫قــرار الدائــرة اجلزائيــة الثانيــة رقــم ‪ 3416009‬يف ‪1434/01/19‬ه ـ‬\n‫ونــص احلاجــة منــه‪ :‬بدراســة الصــك وصــورة ضبطــه تقــرر باألكثريــة‬\n‫املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم قاضــي اســتئناف د‪ .‬ختمــه وتوقيعــه لــه وجهــة نظــر‬\n\n\n                                                                                          ‫‪260‬‬\n\f      ‫قاضــي اســتئناف ختمــه وتوقيعــه رئيــس اســتئناف ختمــه وتوقيعــه وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                          ‫حــرر يف ‪ 1434/02/16‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فبموجــب مــا أحلــق يف ضبطــه فقــد ثبــت لــدي‬\n      ‫اســتالم املدعــي ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫باألصالــة عــن نفســه وبوكالتــه عــن بالوكالــة رقــم ‪ 35288‬وتاريــخ‬\n      ‫‪1433/5/19‬ه ـ الصــادرة مــن كتابــة عــدل املدينــة املنــورة وعــن القرنــي‬\n      ‫باألصالــة عــن نفســها وبواليتهــا علــى ابنتيهــا بالوكالــة رقــم ‪3386236‬‬\n      ‫وتاريــخ ‪1433/5/24‬ه ـ الصــادرة مــن كتابــة عــدل مكــة املكرمــة‬\n      ‫وجــرى تســليمه الشــيك رقــم ‪ 8276449‬وتاريــخ ‪1434/4/17‬ه ـ‬\n      ‫املســحوب علــى مؤسســة النقــد ‪ .....‬مببلــغ وقــدره ثالثمائــة ألــف ريــال‬\n      ‫وبهــذا تعتبــر القضيــة منتهيــة ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/05‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة باملدينــة املنورة رقــم ‪ 33506116‬وتاريخ‬\n      ‫‪1434/1/4‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪........./‬‬\n      ‫القاضــي باحملكمــة العامــة باملدينــة املنــورة برقــم ‪ 33483021‬وتاريــخ‬\n      ‫‪1433/12/29‬ه ـ ‪ ،‬املتضمــن دعــوى‪ .........‬أصالــة ووكالــة ضــد‪.........‬‬\n      ‫دون بباطــن الصــك وبدراســة الصــك‬        ‫بيــت املــال يف دي ــة احملكــوم مبــا ّ‬\n      ‫وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى احلكــم واهلل املوفــق‬\n                        ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪261‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":254,"source_page_end":261,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7499029ae3fcd9cb5cd62562065afddfe6507219224aa2b949ab2318608a6e41","normalized_text_hash":"327639e88d539d806bcb2db89ae847e8e741aaccf688ca8c0cd62c6a86f08d66","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p254-33483021"},{"id":"b78952dd-a903-5520-991a-a52fa11067df","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -حادث مروري مطالبة بدية متوفى بحادث مروري تصديق الوكاالت وحصر الورثة والوالية من اجلهات الرسمية إقرار املدعى عليه إدانة املدعى عليه بنسبة % 50من مسئوولية احلادث ما قرره الفقهاء أن كل من أتلف إنسان ا معصوم ا مباشرة أو بسبب لزمته ديته احلكم على املدعى عليه بدفع الدية مقابل نسبة اخلطأ التي عليه -رفع احلكم حملكمة الاستئناف لوجود قصر.","document_number":"3437583","case_number":"33225640","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/16","year":"1434","subject":"دية -حادث مروري مطالبة بدية متوفى بحادث مروري تصديق الوكاالت وحصر الورثة والوالية من اجلهات الرسمية إقرار املدعى عليه إدانة املدعى عليه بنسبة % 50من مسئوولية احلادث ما قرره الفقهاء أن كل من أتلف إنسان ا معصوم ا مباشرة أو بسبب لزمته ديته احلكم على املدعى عليه بدفع الدية مقابل نسبة اخلطأ التي عليه -رفع احلكم حملكمة الاستئناف لوجود قصر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/2/16 :‬هـ َر ْق ُم‬\n                         ‫ُ‬                ‫َر ْق ُم َّ‬\n                             ‫الص ِّك‪3437583 :‬‬\n                              ‫الدعوى‪33225640 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                      ‫‪ 3452449‬تاريخه‪1434/3/1:‬هـ‬\n\n\n   ‫ديــة ‪ -‬حــادث مــروري ـ مطالبــة بديــة متوفــى بحــادث مــروري ـ تصديــق‬\n   ‫الــوكاالت وحصــر الورثــة والواليــة مــن اجلهــات الرســمية ـ إقــرار‬\n   ‫املدعــى عليــه ـ إدانــة املدعــى عليــه بنســبة ‪ % 50‬مــن مســئوولية احلــادث ـ‬\n   ‫مــا قــرره الفقهــاء أن كل مــن أتلــف إنســان ًا معصومـ ًا مباشــرة أو بســبب‬\n   ‫لزمتــه ديتــه ـ احلكــم علــى املدعــى عليــه بدفــع الديــة مقابــل نســبة‬\n     ‫اخلطــأ التــي عليــه ‪ -‬رفــع احلكــم حملكمــة االســتئناف لوجــود قصــر‪.‬‬\n\n\n\n\n   ‫‪ .1‬مــا ذكــره الفقهــاء أن كل مــن أتلــف إنســان ًا معصوم ـ ًا أو بســبب‪،‬‬\n   ‫لزمتــه ديتــه ‪ .‬ينظــر ( الفــروع ‪ ، 3/6‬اإلقنــاع ‪ ، 139/4‬الــروض املربــع‬\n                                                                    ‫‪. ) 963/2‬‬\n                                 ‫‪ .2‬املادة (‪ )179‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n   ‫حضــر الوكيــل الشــرعي بوكالتــه عــن أحــد الورثــة وحضــر حلضــوره‬\n   ‫الوكيــل اآلخــر باألصالــة عــن نفســه وبالوكالــة عــن بقيــة ورثــة والــده‬\n   ‫ومــن ضمنهــا زوجتيــه والزوجــة الثانيــة مبوجــب واليتهــا علــى أوالدهــا مــن‬\n   ‫مــورث املدعــن وجميــع هــذه الــوكاالت والصكــوك مصــادق عليهــا‬\n   ‫مــن اجلهــات الرســمية حســب التعليمــات وادعــوا بــأن املدعــى عليــه قــد‬\n\n                                                                                       ‫‪262‬‬\n\f      ‫تســبب بدهــس والدهــم ونتــج عــن هــذا وفــاة مورثهــم وقــد أديــن املدعــى‬\n      ‫عليــه بنســبة ‪ % 50‬مــن مســئولية احلــادث ويطلب الوكيــان إلزام املدعى‬\n      ‫عليــه تســليم نصــف ديــة مورثهــم ‪ ،‬بعــرض الدعــوى علــى املدعــى عليــه‬\n      ‫صــادق املدعــى عليــه علــى مــا جــاء بدعــوى املدعــن وأقــر مبســئوليته عــن‬\n      ‫احلادث بنســبة ‪ % 50‬وال مانع لديه من تســليم نصف دية مورثهم ‪ ،‬جرى‬\n      ‫االطــاع علــى صــك حصــر الورثــة الصــادر مــن اليمــن واملصــادق عليــه‬\n      ‫مــن اجلهــات الرســمية ‪ ،‬جــرى االطــاع علــى القــرار الشــرعي املكتســب‬\n      ‫للقطعيــة املتضمــن إدانــة املدعــى عليــه بنســبة ‪ % 50‬مــن مســئولية احلــادث‬\n      ‫وقناعتــه بذلــك ‪ ،‬وإفهامــه بــأن عليــه كفــارة قتــل اخلطــأ وهــي عتــق‬\n      ‫رقبــة فــإن لــم يجــد فصيــام شــهرين متتابعــن ‪ ،‬قــرر الفقهــاء أن كل مــن‬\n      ‫أتلــف إنســان ًا معصومــة مباشــرة أو بســبب لزمتــه ديتــه ‪ ،‬احلكــم علــى‬\n      ‫املدعــى عليــه بتســليم املدعــن أصالــة نصــف ديــة مورثهــم وقدرهــا مائــة‬\n      ‫وخمســون ألــف ريــال ‪ ،‬مت قســمة املبلــغ حســب األنصبــة الشــرعية ـ مت‬\n      ‫حتديــد املبلــغ املقــدر لــكل قاصــر ‪ ،‬إفهــام املدعــى عليــه بــأن لــه حــق‬\n      ‫الرجــوع علــى عاقلتــه ‪ ،‬قنــع املدعــي أصالــة ووكالــة باحلكــم وقنــع بــه‬\n      ‫املدعــى عليــه كذلــك ‪ ،‬مت رفــع احلكــم حملكمــة االســتئناف لتدقيقــه‬\n      ‫ا باملــادة (‪ )179‬مــن نظــام املرافعــات الشــرعية ‪ ،‬صــدق احلكــم‬        ‫عم ـ ً‬\n                                                          ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪263‬‬\n\f‫أمــا بعــد‪:‬‬\n          ‫الســام علــى مــن ال نبـ َّـي بعــده ‪َّ ...‬‬\n                                                    ‫الصــاة و َّ‬\n                                                             ‫احلمــد هلل وحــده‪ ،‬و َّ‬\n‫الشيخ ‪ ، .........‬القاضي باحملكمة‬              ‫فلدي أنا ‪ .........‬القائم بعمل فضيلة َّ‬\n                                                                                    ‫َّ‬\n‫كل مــن ‪ )1( .........‬املواطــن ‪.........‬‬    ‫العامــة يف املدينــة املنـ َّـورة‪ ،‬حضــر ٍّ‬\n                                                                                       ‫َّ‬\n‫الســجلِّ املدنـ ِّـي رقــم (‪ ،).........‬الوكيــل‬     ‫ـعودي اجلنسـ َّـي ِة مبوجــب ِّ‬  ‫‪ُ ،‬سـ ُّ‬\n‫ـرعي عــن املقيــم‪ ، ......... /‬مينـ ِّـي اجلنسـ َّـي ِة مبوجــب ُر ْخ َصــة اإلقامــة‬   ‫الشـ ُّ‬         ‫َّ‬\n‫الصــادرة مــن جــوازات املدينــة املنـ َّـورة برقــم (‪ .).........‬مبوجــب الوكالــة‬                  ‫َّ‬\n‫املنورة رقــم (‪)34105181‬‬        ‫الصــادرة مــن كتابــة العــدل الثَّانيــة يف املدينــة َّ‬         ‫َّ‬\n‫تخولــه احلـ َّـق يف مراجعــة احملاكــم‬       ‫يف ‪1434/01/26‬هــ‪ ......... ،‬و ا َّلتــي ِّ‬\n‫الدعــاوي‪ ،‬واملرافعــة‪ ،‬و املدافعــة‪،‬‬             ‫ـرعية‪ ،‬و املطالبــة‪ ،‬و إقامــة َّ‬        ‫الشـ َّ‬          ‫َّ‬\n‫الشــهود‪،‬‬ ‫الدعــاوى‪ ،‬و الـ َّـر ِّد عليهــا‪ ،‬و طلــب اليمــن‪ ،‬و إحضــار ُّ‬           ‫وســماع َّ‬\n‫الطعــن فيهــا‪ ،‬و اإلجابــة‪،‬و اجلــرح و ال َّتعديــل‪ ،‬و االعتــراض‬             ‫البينــات‪ ،‬و َّ‬‫و ِّ‬\n‫الدعاوى‬ ‫علــى األحــكام‪ ،‬وطلــب االســتئناف‪ ،‬و إنهــاء ما يلــزم يف جميع َّ‬\n‫ـرعية‪ ،‬و اســتالم األعاليــم بخصــوص املطالبــة بديــة‬               ‫الشـ َّ‬‫لــدى احملاكــم َّ‬\n‫مورثهــم‪ ،.........‬و ال َّتو